AttentionOperatorRole = OperatorRole
AttentionPhase = OperatorPhase
AttentionTraceKind = TraceKind


class AttentionMemoryLayout(Enum):
    """Runtime KV-cache layout represented by an attention family."""

    DENSE_KV = "dense_kv"
    LATENT_MLA = "latent_mla"
    FROZEN_DSA = "frozen_dsa"


@dataclass(frozen=True)
class AttentionRuntimeMetaContract:
    """Runtime metadata contract for imported attention profiler rows."""

    expected_runtime_num_kv_heads: int
    runtime_head_size_formula: str
    supported_block_sizes: tuple[int, ...]
    expected_n_q_head: int | None = None

    def __post_init__(self) -> None:
        if self.expected_runtime_num_kv_heads <= 0:
            raise ValueError(
                "expected_runtime_num_kv_heads must be positive, "
                f"got={self.expected_runtime_num_kv_heads!r}"
            )
        if not self.runtime_head_size_formula:
            raise ValueError("runtime_head_size_formula must be non-empty")
        if not self.supported_block_sizes:
            raise ValueError("supported_block_sizes must be non-empty")
        invalid_block_sizes = [
            block_size
            for block_size in self.supported_block_sizes
            if int(block_size) <= 0
        ]
        if invalid_block_sizes:
            raise ValueError(
                "supported_block_sizes must be positive, "
                f"got={invalid_block_sizes!r}"
            )
        if self.expected_n_q_head is not None and self.expected_n_q_head <= 0:
            raise ValueError(
                "expected_n_q_head must be positive when declared, "
                f"got={self.expected_n_q_head!r}"
            )


@dataclass(frozen=True)
class AttentionOperatorSpec(OperatorSpec):
    """Declarative contract for one physical attention operator."""

    _operator_label: ClassVar[str] = "Attention operator"


@dataclass(frozen=True)
class AttentionFamilySpec(OperatorFamilySpec):
    """Declarative contract for one attention operator family."""

    memory_layout: AttentionMemoryLayout
    dense_compatible: bool
    requires_runtime_kv_helpers: bool
    disjoint_model_projection_attrs: tuple[str, ...] = ()
    dsa_frozen: bool = False
    kv_factor: int | None = None
    required_profiling_feature_columns: tuple[str, ...] = ()
    imported_predictor_excluded_feature_columns: tuple[str, ...] = ()
    runtime_num_kv_heads_resolver: Callable[[Any], int] | None = None
    runtime_head_size_resolver: Callable[[Any], int] | None = None
    runtime_meta_contract: AttentionRuntimeMetaContract | None = None

    _family_label: ClassVar[str] = "Attention family"

    def __post_init__(self) -> None:
        super().__post_init__()
        if self.dsa_frozen and self.operators:
            raise ValueError("Frozen DSA family must not enable operator targets")
        if self.dsa_frozen and self.execution_enabled:
            raise ValueError("Frozen DSA family must not be execution enabled")
        projection_attrs = list(self.disjoint_model_projection_attrs)
        duplicate_projection_attrs = sorted(
            {
                attr_name
                for attr_name in projection_attrs
                if projection_attrs.count(attr_name) > 1
            }
        )
        if duplicate_projection_attrs:
            raise ValueError(
                f"Attention family {self.family_id} has duplicate disjoint "
                f"model projection attrs: {duplicate_projection_attrs}"
            )
        if any(not attr_name for attr_name in projection_attrs):
            raise ValueError(
                f"Attention family {self.family_id} has an empty disjoint "
                "model projection attr"
            )
        if self.kv_factor is not None and self.kv_factor <= 0:
            raise ValueError(
                f"Attention family {self.family_id} kv_factor must be positive "
                f"when declared, got={self.kv_factor!r}"
            )
        missing_excluded = tuple(
            column
            for column in self.imported_predictor_excluded_feature_columns
            if column not in self.required_profiling_feature_columns
        )
        if missing_excluded:
            raise ValueError(
                f"Attention family {self.family_id} excludes imported predictor "
                f"columns absent from its profiling schema: {list(missing_excluded)}"
            )

    def resolve_runtime_num_kv_heads(self, config: Any) -> int:
        if self.runtime_num_kv_heads_resolver is None:
            raise ValueError(
                f"Attention family {self.family_id} does not declare a "
                "runtime_num_kv_heads_resolver"
            )
        value = int(self.runtime_num_kv_heads_resolver(config))
        if value <= 0:
            raise ValueError(
                f"Attention family {self.family_id} resolved non-positive "
                f"runtime_num_kv_heads={value!r}"
            )
        return value

    def resolve_runtime_head_size(self, config: Any) -> int:
        if self.runtime_head_size_resolver is None:
            raise ValueError(
                f"Attention family {self.family_id} does not declare a "
                "runtime_head_size_resolver"
            )
        value = int(self.runtime_head_size_resolver(config))
        if value <= 0:
            raise ValueError(
                f"Attention family {self.family_id} resolved non-positive "
                f"runtime_head_size={value!r}"
            )
        return value

    def require_enabled_for_execution(self) -> None:
        if self.dsa_frozen:
            raise NotImplementedError(
                "DSA attention is frozen until a real vLLM/FlashInfer truth "
                "backend and Frontier mapping are approved."
            )
        super().require_enabled_for_execution()

"""
Configuration for the package.
"""

from __future__ import annotations

import dataclasses
import json
import os
import pathlib
import tomllib

import dbt_py.exceptions

CONFIG_FILE = "pyproject.toml"
TOOL_SECTION = ("tool", "dbt-py")
DEFAULT_PACKAGE_NAME = "custom"


@dataclasses.dataclass(frozen=True)
class Config:
    """
    Configuration for the package.
    """

    packages: list[dict[str, str]] = dataclasses.field(default_factory=list)

    @classmethod
    def from_dict(cls, settings: dict) -> Config:
        """
        Create a Config instance from a dictionary.
        """

        return cls(**settings)

    @property
    def hashable_packages(self) -> frozenset[str]:
        """
        Return a frozenset of JSON strings representing the packages.

        This is required for playing nicely with dbt's context modules.
        """
        return frozenset(json.dumps(pkg) for pkg in self.packages)


def _default_packages() -> dict[str, list[dict]]:
    """
    Return the default packages for the configuration.
    """

    # Python-style ref, e.g. `package.module.submodule`
    package_root = os.environ.get("DBT_PY_PACKAGE_ROOT")
    package_name = os.environ.get("DBT_PY_PACKAGE_NAME")
    if package_root or package_name:
        dbt_py.exceptions.warn(
            "Using environment variables for package configuration is deprecated. "
            "Use the `pyproject.toml` file instead.",
            dbt_py.exceptions.DbtPyWarning,
        )

    root = package_root or DEFAULT_PACKAGE_NAME
    name = package_name or package_root

    return {
        "packages": [
            {
                "name": name,
                "path": root,
            }
        ]
    }


def load_config(config_root: pathlib.Path) -> Config:
    """
    Load the configuration from the configuration file.
    """

    conf = config_root / CONFIG_FILE
    default = _default_packages()

    if not conf.exists():
        return Config.from_dict(default)

    return Config.from_dict(
        tomllib.loads(conf.read_text())
        .get(TOOL_SECTION[0], {})
        .get(TOOL_SECTION[1], default)
    )

"""Fetch GitHub stars/forks for ``open_source_projects.yaml``; write ``open_source_github_stats.yaml``."""

from __future__ import annotations

import argparse
import sys
from datetime import datetime, timezone
from pathlib import Path

import yaml

from greek_software_ecosystem.github_stars import (
    fetch_github_repo_stats,
    parse_github_repo_url,
)

_REPO_ROOT = Path(__file__).resolve().parents[2]
OPEN_SOURCE_PROJECTS_YAML = _REPO_ROOT / "_data" / "open_source_projects.yaml"
OSS_STATS_YAML = _REPO_ROOT / "_data" / "open_source_github_stats.yaml"


def _repo_key(url: str) -> str | None:
    p = parse_github_repo_url((url or "").strip())
    if not p:
        return None
    owner, repo = p
    return f"{owner}/{repo}"


def run_fetch() -> int:
    if not OPEN_SOURCE_PROJECTS_YAML.is_file():
        print(f"Missing {OPEN_SOURCE_PROJECTS_YAML}", file=sys.stderr)
        return 1
    try:
        with OPEN_SOURCE_PROJECTS_YAML.open(encoding="utf-8") as f:
            data = yaml.safe_load(f) or {}
    except (yaml.YAMLError, OSError) as e:
        print(f"Failed to read projects YAML: {e}", file=sys.stderr)
        return 1
    projects = data.get("projects") if isinstance(data, dict) else None
    if not isinstance(projects, list):
        print("No projects list in open_source_projects.yaml", file=sys.stderr)
        return 1

    keys_in_order: list[str] = []
    seen: set[str] = set()
    for p in projects:
        if not isinstance(p, dict):
            continue
        url = (p.get("url") or "").strip()
        if not url:
            continue
        key = _repo_key(url)
        if not key or key in seen:
            continue
        seen.add(key)
        keys_in_order.append(key)

    total = len(keys_in_order)
    print(
        f"Fetching GitHub stars/forks for {total} repositories…",
        file=sys.stderr,
        flush=True,
    )

    out_repos: dict[str, dict[str, int | bool | None]] = {}
    archived_count = 0
    for i, key in enumerate(keys_in_order, start=1):
        owner, _, repo = key.partition("/")
        if not repo:
            continue
        stars, forks, archived = fetch_github_repo_stats(owner, repo)
        is_archived = bool(archived)
        if is_archived:
            archived_count += 1
        out_repos[key] = {
            "stars": stars,
            "forks": forks,
            "archived": is_archived,
        }
        if total >= 15 and (i == 1 or i == total or i % 25 == 0):
            print(f"  Progress: {i}/{total}…", file=sys.stderr, flush=True)

    payload = {
        "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "repos": out_repos,
    }
    gen_cmd = "uv run python -m greek_software_ecosystem.fetch_open_source_github_stats"
    header = (
        f"# Auto-generated by: {gen_cmd}\n"
        "# Do not edit by hand. Regenerate after changing open_source_projects.yaml.\n\n"
    )
    OSS_STATS_YAML.parent.mkdir(parents=True, exist_ok=True)
    OSS_STATS_YAML.write_text(
        header + yaml.safe_dump(payload, allow_unicode=True, sort_keys=False),
        encoding="utf-8",
    )
    print(f"Wrote {OSS_STATS_YAML} ({total} repos, {archived_count} archived).", file=sys.stderr)
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Read open_source_projects.yaml, call the GitHub API per repo, "
            "and write open_source_github_stats.yaml for generate_index / readme."
        ),
    )
    parser.parse_args(argv)
    return run_fetch()


if __name__ == "__main__":
    raise SystemExit(main())

