class AnomalyDetectionBuilder:
    """Helper object to build AnomalyDetection check."""

    def __init__(self) -> None:
        self._strategy: AbstractStrategy | None = None
        self._analyzer: AbstractAnalyzer | None = None
        self._check_level: CheckLevel = CheckLevel.Warning
        self._description: str = ""
        self._with_tag_values: dict[str, str] = dict()
        self._after_date: int | None = None
        self._before_date: int | None = None

    def for_analyzer(self, analyzer: AbstractAnalyzer) -> Self:
        """Add an analyzer."""

        self._analyzer = analyzer
        return self

    def with_strategy(self, strategy: AbstractStrategy) -> Self:
        """Add a strategy."""

        self._strategy = strategy
        return self

    def with_check_level(self, level: CheckLevel) -> Self:
        """Set a severity level."""

        self._check_level = level
        return self

    def with_description(self, description: str) -> Self:
        """Add a description."""

        self._description = description
        return self

    def with_tags(self, tags: dict[str, str]) -> Self:
        """Add tags."""

        self._with_tag_values = tags
        return self

    def after_date(self, dt: int) -> Self:
        """Set a minimal dataset date value

        This value will be used to filter out part of
        the timeseries of metrics.
        """
        self._after_date = dt
        return self

    def before_date(self, dt: int) -> Self:
        """Set a maximal dataset date value

        This value will be used to filter out part of
        the timeseries of metrics.
        """

        self._before_date = dt
        return self

    def _validate(self) -> None:
        if self._analyzer is None:
            raise ValueError("Analyzer is not set")
        if self._strategy is None:
            raise ValueError("Strategy is not set")

    def build(self) -> suite.AnomalyDetection:
        self._validate()

        # for mypy
        assert self._strategy is not None
        assert self._analyzer is not None

        return suite.AnomalyDetection(
            anomaly_detection_strategy=self._strategy._to_proto(),
            analyzer=self._analyzer._to_proto(),
            config=suite.AnomalyDetection.AnomalyCheckConfig(
                level=self._check_level._to_proto(),
                description=self._description,
                with_tag_values=self._with_tag_values,
                after_date=self._after_date,
                before_date=self._before_date,
            ),
        )

import typing as t

from sqlmesh import macro
from sqlglot import exp

from sqlmesh.core.macros import MacroEvaluator
from sqlglot.optimizer.normalize_identifiers import normalize_identifiers
from sqlmesh.utils.errors import MacroEvalError, SQLMeshError

@macro()
def star_v2(
    evaluator: MacroEvaluator,
    relation: exp.Table,
    alias: exp.Column = t.cast(exp.Column, exp.column("")),
    exclude: t.Union[exp.Array, exp.Tuple, exp.Column] = exp.Tuple(expressions=[]),
    prefix: exp.Literal = exp.Literal.string(""),
    suffix: exp.Literal = exp.Literal.string(""),
    quote_identifiers: exp.Boolean = exp.true(),
    except_: t.Union[exp.Array, exp.Tuple] = exp.Tuple(expressions=[]),
    select_only: exp.Boolean = exp.false(),
) -> t.List[t.Union[exp.Alias, exp.Column]]:
    """Returns a list of projections for the given relation.

    Args:
        evaluator: MacroEvaluator that invoked the macro
        relation: The relation to select star from
        alias: The alias of the relation
        exclude: Columns to exclude
        prefix: A prefix to use for all selections
        suffix: A suffix to use for all selections
        quote_identifiers: Whether or not quote the resulting aliases, defaults to true
        except_: Alias for exclude (TODO: deprecate this, update docs)
        select_only: Wether or not to only return the projections, without casting and aliasing, defaults to false

    Returns:
        An array of columns.

    Example:
        >>> from sqlglot import parse_one, exp
        >>> from sqlglot.schema import MappingSchema
        >>> from sqlmesh.core.macros import MacroEvaluator
        >>> sql = "SELECT @STAR(foo, bar, exclude := [c], prefix := 'baz_') FROM foo AS bar"
        >>> MacroEvaluator(schema=MappingSchema({"foo": {"a": exp.DataType.build("string"), "b": exp.DataType.build("string"), "c": exp.DataType.build("string"), "d": exp.DataType.build("int")}})).transform(parse_one(sql)).sql()
        'SELECT CAST("bar"."a" AS TEXT) AS "baz_a", CAST("bar"."b" AS TEXT) AS "baz_b", CAST("bar"."d" AS INT) AS "baz_d" FROM foo AS bar'
    """

    if alias and not isinstance(alias, (exp.Identifier, exp.Column)):
        raise SQLMeshError(f"Invalid alias '{alias}'. Expected an identifier.")
    if exclude and not isinstance(exclude, (exp.Array, exp.Tuple, exp.Column)):
        raise SQLMeshError(f"Invalid exclude '{exclude}'. Expected an array or a column.")
    if except_ != exp.tuple_():
        logger.warning(
            "The 'except_' argument in @STAR will soon be deprecated. Use 'exclude' instead."
        )
        if not isinstance(exclude, (exp.Array, exp.Tuple, exp.Column)):
            raise SQLMeshError(f"Invalid exclude_ '{exclude}'. Expected an array or a column.")
    if prefix and not isinstance(prefix, exp.Literal):
        raise SQLMeshError(f"Invalid prefix '{prefix}'. Expected a literal.")
    if suffix and not isinstance(suffix, exp.Literal):
        raise SQLMeshError(f"Invalid suffix '{suffix}'. Expected a literal.")
    if not isinstance(quote_identifiers, exp.Boolean):
        raise SQLMeshError(f"Invalid quote_identifiers '{quote_identifiers}'. Expected a boolean.")
    if not isinstance(select_only, exp.Boolean):
        raise SQLMeshError(f"Invalid select_only '{select_only}'. Expected a boolean.")

    if isinstance(exclude, exp.Column):
        exclude =  exp.Tuple(expressions=[exclude])

    excluded_names = {
        normalize_identifiers(excluded, dialect=evaluator.dialect).name
        for excluded in exclude.expressions
    }
    quoted = quote_identifiers.this
    table_identifier = alias.name or relation.name

    columns_to_types = {
        k: v for k, v in evaluator.columns_to_types(relation).items() if k not in excluded_names
    }

    if select_only:
        return [
            exp.column(column, table=table_identifier, quoted=quoted)
            for column, type_ in columns_to_types.items()
        ]

    if columns_to_types_all_known(columns_to_types):
        return [
            exp.cast(
                exp.column(column, table=table_identifier, quoted=quoted),
                dtype,
                dialect=evaluator.dialect,
            ).as_(f"{prefix.this}{column}{suffix.this}", quoted=quoted)
            for column, dtype in columns_to_types.items()
        ]
    return [
        exp.column(column, table=table_identifier, quoted=quoted).as_(
            f"{prefix.this}{column}{suffix.this}", quoted=quoted
        )
        for column, type_ in columns_to_types.items()
    ]

"""
Detach LadybugDB EBS data volumes when an EC2 instance terminates.

Triggered by an Auto Scaling terminate lifecycle hook (via SNS). Unmounts the
data volume over SSM, asks the volume manager to detach it, and waits for the
volume to reach `available` before releasing the hook. Signals CONTINUE only
when every volume detached cleanly; otherwise ABANDON, so the ASG does not
launch a replacement that races a half-detached volume.
"""

import json
import os

import boto3

# Initialize AWS clients
ec2 = boto3.client("ec2")
ssm = boto3.client("ssm")
asg = boto3.client("autoscaling")
lambda_client = boto3.client("lambda")
dynamodb = boto3.client("dynamodb")


def format_missing_field_error(field_name: str, available_keys: list) -> dict:
  """Format consistent error response for missing fields."""
  return {
    "statusCode": 400,
    "body": f"Missing {field_name}",
    "error": f"No {field_name} found. Available keys: {available_keys}",
  }


def handler(event, context):
  """Process an instance-termination lifecycle event delivered over SNS."""
  try:
    message = json.loads(event["Records"][0]["Sns"]["Message"])
    print(f"Received message: {json.dumps(message, indent=2)}")

    # Handle different message formats
    instance_id = message.get("EC2InstanceId") or message.get("InstanceId")
    lifecycle_hook = message.get("LifecycleHookName")
    asg_name = message.get("AutoScalingGroupName")

    if not instance_id:
      print(
        f"ERROR: No instance ID found in message. Available keys: {list(message.keys())}"
      )
      return format_missing_field_error("instance ID", list(message.keys()))

    if not lifecycle_hook:
      print(
        f"ERROR: No lifecycle hook found in message. Available keys: {list(message.keys())}"
      )
      return format_missing_field_error("lifecycle hook", list(message.keys()))

    if not asg_name:
      print(
        f"ERROR: No ASG name found in message. Available keys: {list(message.keys())}"
      )
      return format_missing_field_error("ASG name", list(message.keys()))

  except Exception as e:
    print(f"ERROR parsing message: {e}")
    print(f"Raw event: {json.dumps(event, indent=2)}")
    return {"statusCode": 500, "body": f"Message parsing error: {e!s}"}

  try:
    print(f"Processing termination for instance: {instance_id}")

    # Get attached volumes
    response = ec2.describe_instances(InstanceIds=[instance_id])
    if not response["Reservations"]:
      print(f"Instance {instance_id} not found")
      return complete_lifecycle(asg_name, lifecycle_hook, instance_id, "CONTINUE")

    instance = response["Reservations"][0]["Instances"][0]
    volumes = []

    for device in instance.get("BlockDeviceMappings", []):
      # Skip only the root volume (xvda), but include data volumes (xvdf, sdf, nvme devices)
      if device["DeviceName"] not in ["/dev/xvda", "/dev/sda1"]:  # Skip root volumes
        volumes.append(
          {"VolumeId": device["Ebs"]["VolumeId"], "Device": device["DeviceName"]}
        )
        print(
          f"Found data volume: {device['Ebs']['VolumeId']} at {device['DeviceName']}"
        )

    # Unmount volumes via SSM (only if instance is still running)
    if instance.get("State", {}).get("Name") == "running":
      for volume in volumes:
        try:
          print(f"Unmounting volume {volume['VolumeId']} from {volume['Device']}")
          ssm.send_command(
            InstanceIds=[instance_id],
            DocumentName="AWS-RunShellScript",
            Parameters={
              "commands": [
                "# Unmount LadybugDB data volume",
                "sync",  # Flush any pending writes
                "umount /mnt/ladybug-data || true",
                "umount /data || true",  # Legacy mount point
              ]
            },
            TimeoutSeconds=30,
          )
        except Exception as e:
          print(f"Failed to unmount (may be expected if instance is terminating): {e}")

    # Call Volume Manager to detach volumes and update registry.
    # Track per-volume success: if any detach fails or the volume doesn't reach
    # `available` state, signal ABANDON. A half-detached volume is the worst
    # outcome — the replacement instance cannot claim it, yet the registry still
    # advertises the graph as served by an instance that is going away.
    all_detached = True
    for volume in volumes:
      volume_id = volume["VolumeId"]
      try:
        print(f"Calling Volume Manager to detach volume {volume_id}")
        response = lambda_client.invoke(
          FunctionName=os.environ["VOLUME_MANAGER_FUNCTION_ARN"],
          InvocationType="RequestResponse",
          Payload=json.dumps(
            {
              "action": "detach_volume",
              "volume_id": volume_id,
              "force": False,  # Don't force detach, let it fail gracefully
            }
          ),
        )

        # Log the response from Volume Manager
        response_payload = json.loads(response["Payload"].read())
        print(f"Volume Manager response for {volume_id}: {response_payload}")
        if response_payload.get("statusCode") != 200:
          all_detached = False
          continue

        # The detach_volume API call returns as soon as EBS accepts the request
        # — the volume is still in `detaching` state for 15-30s afterward. Wait
        # for actual completion before signalling lifecycle CONTINUE; otherwise
        # the replacement instance's volume-manager will race and hit VolumeInUse.
        try:
          waiter = ec2.get_waiter("volume_available")
          waiter.wait(
            VolumeIds=[volume_id], WaiterConfig={"Delay": 5, "MaxAttempts": 36}
          )
          print(f"Volume {volume_id} reached available state")
        except Exception as e:
          print(
            f"Volume {volume_id} did not reach available in 3 min: {e}; "
            f"will signal ABANDON so the next launch doesn't race"
          )
          all_detached = False

      except Exception as e:
        print(f"Failed to detach volume {volume_id}: {e}")
        all_detached = False

    # Clean the stale instance-registry entry for the terminating instance.
    # Without this the registry accumulates dead instance IDs and the routing
    # layer keeps resolving graphs to IPs that no longer exist.
    try:
      registry_table = (
        f"robosystems-graph-{os.environ['ENVIRONMENT']}-instance-registry"
      )
      dynamodb.delete_item(
        TableName=registry_table,
        Key={"instance_id": {"S": instance_id}},
      )
      print(f"Removed {instance_id} from instance-registry")
    except Exception as e:
      print(f"Failed to clean instance-registry for {instance_id}: {e}")

    return complete_lifecycle(
      asg_name,
      lifecycle_hook,
      instance_id,
      "CONTINUE" if all_detached else "ABANDON",
    )

  except Exception as e:
    print(f"Error processing termination: {e}")
    return complete_lifecycle(asg_name, lifecycle_hook, instance_id, "ABANDON")


def complete_lifecycle(asg_name, hook_name, instance_id, result):
  """Release the Auto Scaling lifecycle hook with CONTINUE or ABANDON."""
  asg.complete_lifecycle_action(
    LifecycleHookName=hook_name,
    AutoScalingGroupName=asg_name,
    LifecycleActionResult=result,
    InstanceId=instance_id,
  )
  return {"statusCode": 200, "body": json.dumps(f"Lifecycle completed: {result}")}


# Alias for Lambda container deployment (CloudFormation ImageConfig.Command)
lambda_handler = handler

#!/usr/bin/env python3
"""Probe B.AI LLM API models and smoke-test OpenAI/Anthropic-compatible calls."""

from __future__ import annotations

import argparse
import os
import sys
from typing import Any

import httpx


DEFAULT_BASE_URL = "https://api.b.ai"
DEFAULT_PROMPT = "Reply with exactly: pong"


def main() -> int:
    args = parse_args()
    api_key = args.api_key or os.getenv("BAI_API_KEY")
    if not api_key:
        print("Missing API key. Set BAI_API_KEY or pass --api-key.", file=sys.stderr)
        return 2

    base_url = args.base_url.rstrip("/")
    headers = build_headers(api_key, args.auth)

    with httpx.Client(timeout=args.timeout) as client:
        models = list_models(client, base_url, headers)
        print_models(models)

        if args.list_only:
            return 0

        targets = select_targets(models, args)
        if not targets:
            print("No models matched the requested endpoint/model filters.", file=sys.stderr)
            return 1

        for model in targets:
            model_id = str(model.get("id", ""))
            endpoints = supported_endpoints(model)
            endpoint = choose_endpoint(args.endpoint, endpoints, model_id)
            if endpoint is None:
                print(f"\nSKIP {model_id}: no supported endpoint for --endpoint={args.endpoint}")
                continue

            print(f"\n== {model_id} via {endpoint} ==")
            try:
                result = call_model(
                    client=client,
                    base_url=base_url,
                    headers=headers,
                    endpoint=endpoint,
                    model=model_id,
                    prompt=args.prompt,
                    max_tokens=args.max_tokens,
                )
            except httpx.HTTPStatusError as exc:
                body = exc.response.text[:1000]
                print(f"HTTP {exc.response.status_code}: {body}")
                continue

            print(f"text: {result['text']}")
            if result.get("usage") is not None:
                print(f"usage: {result['usage']}")

    return 0


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="List B.AI models and optionally smoke-test model calls."
    )
    parser.add_argument(
        "--api-key",
        help="B.AI API key. Defaults to BAI_API_KEY environment variable.",
    )
    parser.add_argument(
        "--base-url",
        default=os.getenv("BAI_API_BASE", DEFAULT_BASE_URL),
        help=f"API base URL. Defaults to {DEFAULT_BASE_URL}.",
    )
    parser.add_argument(
        "--auth",
        choices=("bearer", "x-api-key", "both"),
        default="bearer",
        help="Authentication header style. Docs support bearer and x-api-key.",
    )
    parser.add_argument(
        "--endpoint",
        choices=("auto", "openai", "anthropic"),
        default="auto",
        help="Which compatible endpoint to test.",
    )
    parser.add_argument(
        "--model",
        action="append",
        help="Model id to test. Can be passed multiple times. Defaults to one model per endpoint.",
    )
    parser.add_argument(
        "--all",
        action="store_true",
        help="Smoke-test every listed model that matches --endpoint.",
    )
    parser.add_argument(
        "--list-only",
        action="store_true",
        help="Only call GET /v1/models; do not send chat/messages requests.",
    )
    parser.add_argument("--prompt", default=DEFAULT_PROMPT)
    parser.add_argument("--max-tokens", type=int, default=16)
    parser.add_argument("--timeout", type=float, default=60.0)
    return parser.parse_args()


def build_headers(api_key: str, auth: str) -> dict[str, str]:
    headers = {"Content-Type": "application/json"}
    if auth in ("bearer", "both"):
        headers["Authorization"] = f"Bearer {api_key}"
    if auth in ("x-api-key", "both"):
        headers["x-api-key"] = api_key
    return headers


def list_models(
    client: httpx.Client, base_url: str, headers: dict[str, str]
) -> list[dict[str, Any]]:
    response = client.get(f"{base_url}/v1/models", headers=headers)
    response.raise_for_status()
    payload = response.json()
    data = payload.get("data")
    if not isinstance(data, list):
        raise ValueError(f"Unexpected /v1/models response: {payload}")
    return [item for item in data if isinstance(item, dict)]


def print_models(models: list[dict[str, Any]]) -> None:
    print(f"models: {len(models)}")
    for model in models:
        model_id = model.get("id", "")
        owner = model.get("owned_by", "")
        endpoints = ",".join(supported_endpoints(model)) or "-"
        print(f"- {model_id} owner={owner} endpoints={endpoints}")


def supported_endpoints(model: dict[str, Any]) -> list[str]:
    raw = model.get("supported_endpoint_types")
    if isinstance(raw, list):
        return [str(item) for item in raw if item in ("openai", "anthropic")]

    model_id = str(model.get("id", "")).lower()
    if model_id.startswith("claude-"):
        return ["anthropic"]
    return ["openai"]


def select_targets(
    models: list[dict[str, Any]], args: argparse.Namespace
) -> list[dict[str, Any]]:
    if args.model:
        requested = set(args.model)
        return [model for model in models if model.get("id") in requested]

    if args.all:
        return [
            model
            for model in models
            if choose_endpoint(args.endpoint, supported_endpoints(model), str(model.get("id", "")))
        ]

    selected: list[dict[str, Any]] = []
    seen_endpoints: set[str] = set()
    for model in models:
        model_id = str(model.get("id", ""))
        endpoint = choose_endpoint(args.endpoint, supported_endpoints(model), model_id)
        if endpoint and endpoint not in seen_endpoints:
            selected.append(model)
            seen_endpoints.add(endpoint)
        if args.endpoint != "auto" and selected:
            break
        if seen_endpoints == {"openai", "anthropic"}:
            break
    return selected


def choose_endpoint(
    requested: str, endpoints: list[str], model_id: str
) -> str | None:
    if requested != "auto":
        return requested if requested in endpoints else None

    if "claude" in model_id.lower() and "anthropic" in endpoints:
        return "anthropic"
    if "openai" in endpoints:
        return "openai"
    if "anthropic" in endpoints:
        return "anthropic"
    return None


def call_model(
    *,
    client: httpx.Client,
    base_url: str,
    headers: dict[str, str],
    endpoint: str,
    model: str,
    prompt: str,
    max_tokens: int,
) -> dict[str, Any]:
    if endpoint == "openai":
        return call_openai_chat(client, base_url, headers, model, prompt, max_tokens)
    if endpoint == "anthropic":
        return call_anthropic_messages(client, base_url, headers, model, prompt, max_tokens)
    raise ValueError(f"Unsupported endpoint: {endpoint}")


def call_openai_chat(
    client: httpx.Client,
    base_url: str,
    headers: dict[str, str],
    model: str,
    prompt: str,
    max_tokens: int,
) -> dict[str, Any]:
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "stream": False,
        "max_tokens": max_tokens,
        "temperature": 0,
    }
    response = client.post(
        f"{base_url}/v1/chat/completions", headers=headers, json=payload
    )
    response.raise_for_status()
    data = response.json()
    choice = data.get("choices", [{}])[0]
    message = choice.get("message") or {}
    return {
        "text": message.get("content", ""),
        "usage": data.get("usage"),
        "raw_model": data.get("model"),
    }


def call_anthropic_messages(
    client: httpx.Client,
    base_url: str,
    headers: dict[str, str],
    model: str,
    prompt: str,
    max_tokens: int,
) -> dict[str, Any]:
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": prompt}],
        "max_tokens": max_tokens,
        "stream": False,
        "temperature": 0,
    }
    response = client.post(f"{base_url}/v1/messages", headers=headers, json=payload)
    response.raise_for_status()
    data = response.json()
    return {
        "text": extract_anthropic_text(data),
        "usage": data.get("usage"),
        "raw_model": data.get("model"),
    }


def extract_anthropic_text(data: dict[str, Any]) -> str:
    content = data.get("content")
    if isinstance(content, str):
        return content
    if not isinstance(content, list):
        return ""

    parts: list[str] = []
    for block in content:
        if isinstance(block, dict) and block.get("type") == "text":
            parts.append(str(block.get("text", "")))
    return "".join(parts)


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Validate registry.yaml: check all entries point to existing SKILL.md files
with valid YAML frontmatter."""

import re
import sys
from pathlib import Path

import yaml


ROOT = Path(__file__).resolve().parent.parent
REGISTRY_PATH = ROOT / "registry.yaml"
REQUIRED_FRONTMATTER = {"name", "description"}
TAG_PATTERN = re.compile(r"^[a-z0-9][a-z0-9-]*$")


def parse_frontmatter(skill_path: Path) -> dict:
    """Extract YAML frontmatter from a SKILL.md file."""
    text = skill_path.read_text(encoding="utf-8")
    if not text.startswith("---"):
        return {}
    end = text.index("---", 3)
    return yaml.safe_load(text[3:end]) or {}


def validate() -> list[str]:
    errors: list[str] = []

    if not REGISTRY_PATH.exists():
        errors.append(f"Registry not found: {REGISTRY_PATH}")
        return errors

    with open(REGISTRY_PATH, encoding="utf-8") as f:
        registry = yaml.safe_load(f)

    entries = registry.get("entries", [])
    if not entries:
        errors.append("Registry has no entries")
        return errors

    seen_names: set[str] = set()
    for i, entry in enumerate(entries):
        name = entry.get("name", f"<entry {i}>")

        # Duplicate name check
        if name in seen_names:
            errors.append(f"Duplicate entry name: {name}")
        seen_names.add(name)

        # Required registry fields
        for field in ("name", "path", "category", "description"):
            if not entry.get(field):
                errors.append(f"[{name}] Missing registry field: {field}")

        # Optional tags field
        tags = entry.get("tags")
        if tags is not None:
            if not isinstance(tags, list):
                errors.append(f"[{name}] tags must be a list, got {type(tags).__name__}")
            else:
                for t in tags:
                    if not isinstance(t, str):
                        errors.append(f"[{name}] tag must be a string, got {type(t).__name__}: {t!r}")
                    elif not TAG_PATTERN.match(t):
                        errors.append(
                            f"[{name}] tag '{t}' must be lowercase kebab-case "
                            f"(matching {TAG_PATTERN.pattern})"
                        )
                if len(tags) != len(set(tags)):
                    errors.append(f"[{name}] tags has duplicates: {tags}")

        # File existence
        skill_path = ROOT / entry.get("path", "")
        if not skill_path.exists():
            errors.append(f"[{name}] SKILL.md not found: {entry.get('path')}")
            continue

        # Frontmatter validation
        fm = parse_frontmatter(skill_path)
        missing = REQUIRED_FRONTMATTER - set(fm.keys())
        if missing:
            errors.append(f"[{name}] Missing frontmatter: {missing}")

        # Name consistency
        if fm.get("name") and fm["name"] != name:
            errors.append(
                f"[{name}] Frontmatter name mismatch: "
                f"registry='{name}' vs file='{fm['name']}'"
            )

    return errors


def main():
    errors = validate()
    if errors:
        print(f"FAILED — {len(errors)} error(s):", file=sys.stderr)
        for e in errors:
            print(f"  ✗ {e}", file=sys.stderr)
        sys.exit(1)
    else:
        print(f"OK — {len(yaml.safe_load(REGISTRY_PATH.read_text())['entries'])} entries validated")


if __name__ == "__main__":
    main()

"""Cloudflare bypass utilities using cloudscraper."""

import asyncio
from importlib.metadata import PackageNotFoundError, version as package_version
import logging
