"""Prepare a release by updating the package version and release notes."""

import re
from datetime import date
from enum import Enum
from pathlib import Path
from typing import Annotated

import typer

VERSION_PATTERN = re.compile(r'(?m)^__version__ = "(\d+\.\d+\.\d+)"$')
VERSION_HEADING_PATTERN = re.compile(r"(?m)^## (\d+\.\d+\.\d+)(?: \([^)]+\))?$")
RELEASE_NOTES_HEADER = "# Release Notes\n\n"
LATEST_CHANGES_HEADER = "## Latest Changes"


class BumpType(str, Enum):
    major = "major"
    minor = "minor"
    patch = "patch"


app = typer.Typer()


def parse_version(version: str) -> tuple[int, int, int]:
    match = re.fullmatch(r"\d+\.\d+\.\d+", version)
    if not match:
        raise ValueError(f"Invalid version: {version!r}. Expected format: X.Y.Z")
    major, minor, patch = version.split(".")
    return int(major), int(minor), int(patch)


def get_current_version(content: str, version_file: Path) -> str:
    matches = list(VERSION_PATTERN.finditer(content))
    if len(matches) != 1:
        raise RuntimeError(
            f"Expected exactly one __version__ assignment in {version_file}, "
            f"found {len(matches)}"
        )
    return matches[0].group(1)


def bump_version(version: str, bump: BumpType) -> str:
    major, minor, patch = parse_version(version)
    if bump is BumpType.major:
        return f"{major + 1}.0.0"
    if bump is BumpType.minor:
        return f"{major}.{minor + 1}.0"
    return f"{major}.{minor}.{patch + 1}"


def update_version_file(content: str, version: str, version_file: Path) -> str:
    current_version = get_current_version(content, version_file)
    if parse_version(version) <= parse_version(current_version):
        raise RuntimeError(
            f"New version {version} must be greater than current version {current_version}"
        )
    return VERSION_PATTERN.sub(f'__version__ = "{version}"', content, count=1)


def update_release_notes(
    content: str, version: str, release_date: date, release_notes_file: Path
) -> str:
    if not content.startswith(RELEASE_NOTES_HEADER):
        raise RuntimeError(
            f"{release_notes_file} must start with {RELEASE_NOTES_HEADER!r}"
        )
    if re.search(rf"^## {re.escape(version)}(?: \([^)]+\))?$", content, re.M):
        raise RuntimeError(f"Release notes already contain a section for {version}")

    latest_header = f"{RELEASE_NOTES_HEADER}{LATEST_CHANGES_HEADER}\n"
    if not content.startswith(latest_header):
        raise RuntimeError(f"{release_notes_file} must start with {latest_header!r}")

    release_header = f"## {version} ({release_date.isoformat()})"
    return content.replace(
        latest_header,
        f"{RELEASE_NOTES_HEADER}{LATEST_CHANGES_HEADER}\n\n{release_header}\n",
        1,
    )


def get_release_notes_body(content: str, version: str, release_notes_file: Path) -> str:
    version_heading = re.compile(rf"(?m)^## {re.escape(version)}(?: \([^)]+\))?$")
    match = version_heading.search(content)
    if not match:
        raise RuntimeError(
            f"Could not find release notes section for {version} in {release_notes_file}"
        )

    next_match = VERSION_HEADING_PATTERN.search(content, match.end())
    end = next_match.start() if next_match else len(content)
    body = content[match.end() : end].strip()
    if not body:
        raise RuntimeError(
            f"Release notes section for {version} in {release_notes_file} is empty"
        )
    return f"{body}\n"


@app.command()
def prepare(
    bump: Annotated[
        BumpType,
        typer.Argument(
            envvar="PREPARE_RELEASE_BUMP",
            help="The release bump to make: major, minor, or patch.",
        ),
    ],
    version_file: Annotated[
        Path,
        typer.Option(
            envvar="PREPARE_RELEASE_VERSION_FILE",
            exists=True,
            file_okay=True,
            dir_okay=False,
            readable=True,
            writable=True,
            help="Path to the Python file containing the __version__ assignment.",
        ),
    ],
    release_notes_file: Annotated[
        Path,
        typer.Option(
            envvar="PREPARE_RELEASE_RELEASE_NOTES_FILE",
            exists=True,
            file_okay=True,
            dir_okay=False,
            readable=True,
            writable=True,
            help="Path to the release notes Markdown file.",
        ),
    ],
    release_date: Annotated[
        str,
        typer.Option(
            "--date",
            envvar="PREPARE_RELEASE_DATE",
            help="Release date in YYYY-MM-DD format. Defaults to today.",
        ),
    ] = date.today().isoformat(),
) -> None:
    parsed_release_date = date.fromisoformat(release_date or date.today().isoformat())

    version_file_content = version_file.read_text()
    release_notes_content = release_notes_file.read_text()
    version = bump_version(
        get_current_version(version_file_content, version_file), bump
    )

    version_file.write_text(
        update_version_file(version_file_content, version, version_file)
    )
    release_notes_file.write_text(
        update_release_notes(
            release_notes_content, version, parsed_release_date, release_notes_file
        )
    )

    typer.echo(f"Prepared release {version} ({parsed_release_date.isoformat()})")


@app.command()
def current_version(
    version_file: Annotated[
        Path,
        typer.Option(
            envvar="PREPARE_RELEASE_VERSION_FILE",
            exists=True,
            file_okay=True,
            dir_okay=False,
            readable=True,
            help="Path to the Python file containing the __version__ assignment.",
        ),
    ],
) -> None:
    typer.echo(get_current_version(version_file.read_text(), version_file))


@app.command()
def release_notes(
    version_file: Annotated[
        Path,
        typer.Option(
            envvar="PREPARE_RELEASE_VERSION_FILE",
            exists=True,
            file_okay=True,
            dir_okay=False,
            readable=True,
            help="Path to the Python file containing the __version__ assignment.",
        ),
    ],
    release_notes_file: Annotated[
        Path,
        typer.Option(
            envvar="PREPARE_RELEASE_RELEASE_NOTES_FILE",
            exists=True,
            file_okay=True,
            dir_okay=False,
            readable=True,
            help="Path to the release notes Markdown file.",
        ),
    ],
) -> None:
    version = get_current_version(version_file.read_text(), version_file)
    typer.echo(
        get_release_notes_body(
            release_notes_file.read_text(), version, release_notes_file
        ),
        nl=False,
    )


if __name__ == "__main__":
    app()

import asyncio
from asyncio import Event, Task
from typing import Any, Callable, Coroutine, Dict, Tuple

from fastapi import HTTPException, Request

from models import ClientDisconnectedError


async def check_client_connection(req_id: str, http_request: Request) -> bool:
    """
    Checks if the client is still connected.
    Returns True if connected, False if disconnected.
    """
    try:
        if hasattr(http_request, "_receive"):
            try:
                # Use a very short timeout to check for disconnect message
                # _receive is a private Starlette/FastAPI method that returns a coroutine
                receive_obj = http_request  # type: ignore[misc]
                receive_coro: Coroutine[Any, Any, Dict[str, Any]] = (
                    receive_obj._receive()
                )  # type: ignore[misc]
                receive_task: Task[Dict[str, Any]] = asyncio.create_task(receive_coro)
                done, pending = await asyncio.wait([receive_task], timeout=0.01)

                if done:
                    message = receive_task.result()
                    if message.get("type") == "http.disconnect":
                        return False
                else:
                    # Cancel the task if it didn't complete immediately
                    receive_task.cancel()
                    try:
                        await receive_task
                    except asyncio.CancelledError:
                        pass
                    # If it didn't complete immediately, proceed to fallback check
            except asyncio.CancelledError:
                raise
            except Exception:
                # If checking fails, proceed to fallback
                pass

        # Fallback to is_disconnected() if available (Starlette/FastAPI)
        # Wrap in wait_for to prevent infinite hang in some ASGI implementations
        if hasattr(http_request, "is_disconnected"):
            try:
                # Handle both sync and async versions for better mock compatibility
                res = http_request.is_disconnected()
                if asyncio.iscoroutine(res):
                    if await asyncio.wait_for(res, timeout=0.01):
                        return False
                elif res:
                    return False
            except (asyncio.TimeoutError, asyncio.CancelledError):
                # If it times out, it's likely still connected
                return True

        return True
    except asyncio.CancelledError:
        raise
    except Exception as e:
        # Re-raise to allow caller to log/handle
        raise e


async def enhanced_disconnect_monitor(
    req_id: str,
    http_request: Request,
    completion_event: asyncio.Event,
    logger: Any,
) -> bool:
    """
    Monitors for client disconnect during streaming.
    Returns True if disconnected, False otherwise.
    """
    disconnect_detection_count = 0
    while not completion_event.is_set():
        try:
            is_connected = await check_client_connection(req_id, http_request)
            if not is_connected:
                disconnect_detection_count += 1
                if disconnect_detection_count >= 3:
                    logger.info(
                        f"[{req_id}] Client disconnect confirmed during streaming."
                    )
                    completion_event.set()
                    return True
            else:
                disconnect_detection_count = 0
            await asyncio.sleep(0.2)
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[{req_id}] Error in enhanced_disconnect_monitor: {e}")
            break
    return False


async def non_streaming_disconnect_monitor(
    req_id: str,
    http_request: Request,
    result_future: asyncio.Future,
    logger: Any,
) -> bool:
    """
    Monitors for client disconnect during non-streaming processing.
    Returns True if disconnected, False otherwise.
    """
    while not result_future.done():
        try:
            is_connected = await check_client_connection(req_id, http_request)
            if not is_connected:
                logger.info(
                    f"[{req_id}] Client disconnect detected during non-streaming."
                )
                if not result_future.done():
                    result_future.set_exception(
                        HTTPException(status_code=499, detail="Client disconnected")
                    )
                return True
            await asyncio.sleep(0.3)
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[{req_id}] Error in non_streaming_disconnect_monitor: {e}")
            break
    return False


async def setup_disconnect_monitoring(
    req_id: str, http_request: Request, result_future
) -> Tuple[Event, asyncio.Task, Callable]:
    from api_utils.server_state import state

    logger = state.logger

    client_disconnected_event = Event()
    disconnect_count = 0
    disconnect_threshold = 5  # Require 5 consecutive disconnect signals (1.5 seconds)

    async def check_disconnect_periodically():
        nonlocal disconnect_count
        while not client_disconnected_event.is_set():
            try:
                is_connected = await check_client_connection(req_id, http_request)
                if not is_connected:
                    disconnect_count += 1
                    if disconnect_count >= disconnect_threshold:
                        logger.info(
                            f"[{req_id}] Active detection of client disconnect (consecutive {disconnect_count} times)."
                        )
                        client_disconnected_event.set()
                        if not result_future.done():
                            result_future.set_exception(
                                HTTPException(
                                    status_code=499,
                                    detail=f"[{req_id}] Client closed the request",
                                )
                            )
                        break
                    else:
                        logger.debug(
                            f"[{req_id}] Active detection of potential disconnect (round {disconnect_count}/{disconnect_threshold})"
                        )
                else:
                    disconnect_count = 0  # Reset counter on successful connection

                await asyncio.sleep(0.3)
            except asyncio.CancelledError:
                # Task cancelled, exit gracefully
                break
            except Exception as e:
                logger.error(f"(Disco Check Task) Error: {e}")
                client_disconnected_event.set()
                if not result_future.done():
                    result_future.set_exception(
                        HTTPException(
                            status_code=500,
                            detail=f"[{req_id}] Internal disconnect checker error: {e}",
                        )
                    )
                break

    disconnect_check_task = asyncio.create_task(check_disconnect_periodically())

    def check_client_disconnected(stage: str = "") -> bool:
        if client_disconnected_event.is_set():
            logger.info(f"Client disconnected detected at stage: '{stage}'")
            raise ClientDisconnectedError(
                f"[{req_id}] Client disconnected at stage: {stage}"
            )
        return False

    return client_disconnected_event, disconnect_check_task, check_client_disconnected

#!/usr/bin/env python3
"""
Check search engine indexing status for Nabla documentation
"""

import time

import requests


def check_google_indexing():
    """Check Google indexing status"""
    print("🔍 Checking Google indexing status...")

    # Check site: operator results
    queries = [
        "site:www.nablaml.com",
        "site:www.nablaml.com/api/",
        "site:www.nablaml.com/examples/",
        "nabla python library gpu",
        '"nabla-ml" python',
    ]

    for query in queries:
        print(f"\n📊 Query: {query}")
        try:
            # Use requests to check if pages exist and are accessible
            if query.startswith("site:"):
                domain = query.replace("site:", "")
                if "/" in domain:
                    url = f"https://{domain}"
                else:
                    url = f"https://{domain}"

                response = requests.get(url, timeout=10)
                if response.status_code == 200:
                    print(f"   ✅ URL accessible: {url}")
                else:
                    print(
                        f"   ❌ URL not accessible: {url} (Status: {response.status_code})"
                    )

            time.sleep(1)  # Be respectful

        except Exception as e:
            print(f"   ❌ Error checking: {e}")


def check_structured_data():
    """Check if structured data is valid"""
    print("\n🏗️  Checking structured data...")

    test_urls = [
        "https://www.nablaml.com/",
        "https://www.nablaml.com/api/tensor.html",
        "https://www.nablaml.com/examples/index.html",
    ]

    for url in test_urls:
        try:
            response = requests.get(url, timeout=10)
            if "application/ld+json" in response.text:
                # Extract JSON-LD
                import json
                import re

                json_ld_match = re.search(
                    r'<script type="application/ld\+json"[^>]*>(.*?)</script>',
                    response.text,
                    re.DOTALL,
                )

                if json_ld_match:
                    try:
                        json_data = json.loads(json_ld_match.group(1))
                        print(f"   ✅ Valid JSON-LD found in {url}")
                        if "@type" in json_data:
                            print(f"      Type: {json_data['@type']}")
                        if "name" in json_data:
                            print(f"      Name: {json_data['name']}")
                    except json.JSONDecodeError:
                        print(f"   ❌ Invalid JSON-LD in {url}")
                else:
                    print(f"   ❌ No JSON-LD script tag found in {url}")
            else:
                print(f"   ❌ No structured data found in {url}")

        except Exception as e:
            print(f"   ❌ Error checking {url}: {e}")


def check_meta_tags():
    """Check critical meta tags across key pages"""
    print("\n🏷️  Checking meta tags...")

    test_urls = [
        "https://www.nablaml.com/",
        "https://www.nablaml.com/api/tensor.html",
        "https://www.nablaml.com/examples/index.html",
    ]

    for url in test_urls:
        try:
            response = requests.get(url, timeout=10)
            html = response.text.lower()

            print(f"\n   📄 {url}:")

            # Check critical elements
            checks = {
                "Title": "<title>" in html,
                "Meta Description": 'name="description"' in html,
                "Canonical URL": 'rel="canonical"' in html,
                "Open Graph": 'property="og:' in html,
                "Twitter Cards": 'name="twitter:' in html,
                "Viewport": 'name="viewport"' in html,
            }

            for check, passed in checks.items():
                status = "✅" if passed else "❌"
