]

_COMPILED_MODULES: Final = frozenset((
    'dmr.envs',
    'dmr.compiled',
    'dmr._compiled',
))


@pytest.fixture
def clean_modules() -> CleanModules:
    """Fixture to clean required modules."""

    @contextmanager
    def factory(
        names: Set[str] = _COMPILED_MODULES,
    ) -> Generator[dict[str, ModuleType]]:
