_print_ = print


def print(*args, **kwargs):
    '''
    modified `print()` function

    replaced secret to `[SECRET]`

    original: `_print_()`
    '''
    new_args = []
    for i in args:
        new_args.append(str(i).replace(str(SECRET), '[SECRET]'))
