                    proxies={
                        'all': PROXY
                    },
                    **kwargs
                )
            else:
                return requests.get(
                    url=url,
                    **kwargs
                )
        except Exception as e:
            retries -= 1
            if retries:
                print(f'ing - Request error: {e}, retrying... ({retries} left)')
                sleep(0.5)
                continue
