#!/usr/bin/env python3
"""Check that every skill has description-tuning eval coverage.

Cross-references skills/ against evals/triggering.json and fails if any skill is
missing, has no should_trigger / should_not_trigger prompts, or references a skill
that does not exist. This does not run an agent; it guarantees the eval set stays
in sync with the catalog so description tuning covers every skill.

Uses only the Python 3 standard library.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SKILLS_DIR = ROOT / "skills"
EVALS = ROOT / "evals" / "triggering.json"


def main() -> int:
    skills = {p.parent.name for p in SKILLS_DIR.rglob("SKILL.md")}
    data = json.loads(EVALS.read_text(encoding="utf-8"))
    cases = {c["skill"]: c for c in data["cases"]}

    errors: list[str] = []

    for name in sorted(skills - cases.keys()):
        errors.append(f"skill '{name}' has no eval case")
    for name in sorted(cases.keys() - skills):
        errors.append(f"eval case '{name}' references a non-existent skill")

    for name, case in sorted(cases.items()):
        if not case.get("should_trigger"):
            errors.append(f"'{name}' has no should_trigger prompts")
        if not case.get("should_not_trigger"):
            errors.append(f"'{name}' has no should_not_trigger prompts")

    if errors:
        for err in errors:
            print(f"FAIL - {err}")
        print(f"\n{len(errors)} eval coverage problem(s)")
        return 1

    print(f"ok - {len(skills)} skills all have trigger/non-trigger eval coverage")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""A37 — does a 3-step update chain leave the OLDEST claim active?

One observation could be LLM non-determinism. Run the triangle three times with
different subjects and report how often the oldest row survives as `active`
alongside the newest.
"""

import json
import time
import urllib.error
import urllib.request

BASE, KEY = "http://localhost:8000", "dev-admin-key"
SETTLE = 55


def call(method, path, body=None):
    req = urllib.request.Request(
        BASE + path,
        method=method,
        headers={"X-API-Key": KEY, "Content-Type": "application/json"},
        data=json.dumps(body).encode() if body is not None else None,
    )
    try:
        with urllib.request.urlopen(req, timeout=180) as r:
            return r.status, json.loads(r.read().decode(), strict=False)
    except urllib.error.HTTPError as e:
        return e.code, {"raw": e.read().decode()[:150]}


def w(t, c):
    return call(
        "POST", "/api/v1/memories", {"tenant_id": t, "agent_id": "a37", "content": c}
    )[1]


def st(t, mid):
    s, m = call("GET", f"/api/v1/memories/{mid}?tenant_id={t}")
    return (m.get("status"), m.get("supersedes_id")) if s == 200 else (f"<{s}>", None)


subjects = [
    ("deploy window", ["01:00 UTC", "03:00 UTC", "05:00 UTC"]),
    ("primary oncall", ["Marta", "Tomas", "Wei"]),
    ("build agent pool size", ["4 workers", "8 workers", "16 workers"]),
]
stale_survives = 0
for n, (subj, vals) in enumerate(subjects):
    salt = f"{int(time.time())}{n}"[-7:]
    T = f"a37r{salt}"
    ids = []
    for i, v in enumerate(vals):
        m = w(T, f"The {salt} {subj} is {v}.")
        ids.append(m.get("id"))
        time.sleep(SETTLE if i else 5)
    rows = [(lbl, *st(T, i)) for lbl, i in zip("ABC", ids)]
    print(f"\n--- run {n + 1}: {subj}")
    for lbl, s, sup in rows:
        print(f"    {lbl}: status={s:10s} supersedes={str(sup)[:8]}")
    oldest_status = rows[0][1]
    newest_status = rows[-1][1]
    bad = oldest_status not in ("outdated", "conflicted") and newest_status == "active"
    stale_survives += bad
    print(
        f"    oldest still active alongside newest: {'YES  <-- stale claim live' if bad else 'no'}"
    )

print(f"\nA37 RESULT: oldest claim survived in {stale_survives}/{len(subjects)} runs")

from collections import defaultdict, OrderedDict
from collections.abc import Callable, Iterator
from graphlib import TopologicalSorter
from typing import Any, Optional, Sequence, Union

from radient.utils.flatten_inputs import flattened


class Workflow:
    """Workflows are used to chain together independent tasks together in a
    DAG. The output of each task is maintained in a table and passed to
    subsequent tasks that need the corresponding result.
    """

    def __init__(self):
        self._runners = OrderedDict()
        self._dependencies = {}
        self._runner_graph = None

    def __call__(self, *args, **kwargs) -> Any:
        self.compile()
        return self.execute(*args, **kwargs)

    def add(
        self,
        runner: Callable,
        name: str,
        dependencies: Optional[Sequence[str]] = None
    ) -> "Workflow":

        # By default, new tasks have a single dependency: the preceding task.
        if not dependencies:
            names = list(self._runners.keys())
            dependencies = (names[-1],) if names else ()
        self._dependencies[name] = dependencies

        self._runners[name] = runner

        return self

    def compile(self):
        self._runner_graph = TopologicalSorter(self._dependencies)
        self._all_outputs = defaultdict(list)

    def execute(
        self,
        extra_vars: Optional[dict[str, dict[str, Any]]] = None,
        **kwargs
    ) -> Any:
        if self._runner_graph is None:
            raise ValueError("call compile() first")

        extra_vars = extra_vars or {}

        # TODO(fzliu): workflows may be persistent rather than returning a
        # single output or set of outputs
        for name in self._runner_graph.static_order():
            inputs = []
            if not self._dependencies[name]:
                # A task with no dependencies is a "seed" task.
                inputs.append([kwargs])
            else:
                for d in self._dependencies[name]:
                    inputs.append(self._all_outputs[d][-1])

            # Ignore if any of the results are `None`.
            if [None] in inputs:
                self._all_outputs[name].append([None])
                continue

            # A task can return a single item or multiple items in a list.
            outputs = []
            for args, _ in flattened(*inputs):
                kwargs = {k: v for d in args for k, v in d.items()}
                kwargs.update(extra_vars.get(name, {}))
                result = self._runners[name](**kwargs)
                if isinstance(result, list):
                    outputs.extend(result)
                else:
                    outputs.append(result)
            self._all_outputs[name].append(outputs)

        return self._all_outputs[name]

#!/usr/bin/env python3
"""
Qwen3 ASR demo for OpenArc's OpenAI-compatible transcription endpoint.

Uses the OpenAI Python library. Assumes the server is already running.

Usage:
    OPENARC_API_KEY=sk-... python demos/qwen3_asr_transcribe.py /path/to/audio.wav --model qwen3_asr
"""

import argparse
import json
import os
from pathlib import Path

from openai import OpenAI

# Qwen3 ASR config for openarc_asr.qwen3_asr (audio_base64 injected from file)
QWEN3_ASR_CONFIG = {
    "language": None,
    "max_tokens": 1024,
    "max_chunk_sec": 30.0,
    "search_expand_sec": 5.0,
    "min_window_ms": 100.0,
}


def transcribe_audio(
    base_url: str, api_key: str, model_name: str, wav_path: Path
) -> dict:
    """Transcribe audio file using Qwen3 ASR. Returns response dict (text, metrics, etc.)."""
    if not wav_path.exists() or not wav_path.is_file():
        raise FileNotFoundError(f"Audio file not found: {wav_path}")

    client = OpenAI(base_url=f"{base_url.rstrip('/')}/v1", api_key=api_key)

    with wav_path.open("rb") as f:
        response = client.audio.transcriptions.create(
            model=model_name,
            file=f,
            response_format="verbose_json",
            extra_body={
                "openarc_asr": json.dumps({"qwen3_asr": QWEN3_ASR_CONFIG}),
            },
        )

    return response.model_dump() if hasattr(response, "model_dump") else dict(response)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Transcribe audio with a loaded Qwen3 ASR model in OpenArc."
    )
    parser.add_argument("audio_path", type=Path, help="Path to WAV/compatible audio file")
    parser.add_argument(
        "--model", default="qwen3_asr", help="Loaded OpenArc model name"
    )
    parser.add_argument(
        "--base-url", default="http://localhost:8003", help="OpenArc server base URL"
    )
    args = parser.parse_args()

    api_key = os.environ.get("OPENARC_API_KEY")
    if not api_key:
        raise SystemExit("OPENARC_API_KEY environment variable must be set")

    payload = transcribe_audio(args.base_url, api_key, args.model, args.audio_path)
    text = payload.get("text", "")
    language = payload.get("language")
    metrics = payload.get("metrics", {}) or {}

    print("\n=== Qwen3 ASR Transcription ===")
    if language:
        print(f"Language: {language}")
    print(f"Text: {text}\n")
    if metrics:
        print("Metrics:")
        for key, value in metrics.items():
            print(f"  {key}: {value}")


if __name__ == "__main__":
    main()

# imports
import pickle
import numpy as np
from flask import Flask, request, jsonify

# Load the trained model
with open("model.pkl", "rb") as f:
    model = pickle.load(f)

app = Flask(__name__)

@app.route("/")
def home():
    return "Welcome to the ML Model API!"

# Map class index to species
species = ["setosa", "versicolor", "virginica"]

@app.route("/predict", methods=["POST"])
def predict():
    data = request.get_json(force=True)

    # Example input format: {"features": [5.1, 3.5, 1.4, 0.2]}
    features = np.array(data['features']).reshape(1, -1)
    if features is None:
        return jsonify({"error": "Missing 'features' in request"}), 400

    try:
        prediction = model.predict(features)[0]
        species_name = species[prediction]
        return jsonify({"prediction": species_name})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)

