    "RISK_TYPE": [r"数据泄露", r"系统故障", r"合规风险", r"操作风险", r"技术风险", r"业务风险", r"财务风险", r"权限滥用"],
    "CONTROL_TYPE": [r"访问控制", r"数据加密", r"审计日志", r"备份恢复", r"变更管理", r"事件响应", r"权限管理", r"职责分离"],
    "PROCESS_TYPE": [r"用户管理", r"财务报告", r"数据备份", r"系统变更", r"安全监控", r"风险评估", r"合规检查"],
    "SYSTEM_TYPE": [r"ERP系统", r"CRM系统", r"财务系统", r"人力资源系统", r"OA系统", r"邮件系统", r"数据库系统"],
}

RELATION_PATTERNS: Dict[str, List[str]] = {
    "COVERS": [r"(.{1,40}?)(?:标准|规范|制度)?(?:覆盖|适用于|要求)(.{1,40}?)(?:。|；|;|$)"],
    "MITIGATES": [r"(.{1,40}?)(?:缓解|降低|减少|控制)(.{1,40}?)(?:。|；|;|$)"],
    "IMPLEMENTS": [r"(.{1,40}?)(?:实施|执行|建立|落地)(.{1,40}?)(?:。|；|;|$)"],
    "RELATED_TO": [r"(.{1,40}?)(?:涉及|影响|关联)(.{1,40}?)(?:。|；|;|$)"],
}


class EntityExtractor:
    def extract_entities(self, text: str, language: str = "auto") -> List[Dict[str, Any]]:
        entities = []
        for entity_type, patterns in AUDIT_PATTERNS.items():
            for pattern in patterns:
                for match in re.finditer(pattern, text, re.IGNORECASE):
                    entities.append(
                        {
                            "text": match.group().strip(),
                            "label": entity_type,
                            "start": match.start(),
                            "end": match.end(),
                            "confidence": 0.9,
                        }
                    )
        return self._dedupe(entities)

    def _dedupe(self, entities: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        seen = set()
        result = []
        for entity in entities:
            key = (entity["text"], entity["label"])
            if key in seen:
                continue
            seen.add(key)
            result.append(entity)
        return result


class RelationExtractor:
    def extract_relations(self, text: str, entities: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        relations = []
        for relation_type, patterns in RELATION_PATTERNS.items():
            for pattern in patterns:
                for match in re.finditer(pattern, text, re.IGNORECASE):
                    source = self._find_entity(match.group(1), entities)
                    target = self._find_entity(match.group(2), entities)
                    if source and target and source["text"] != target["text"]:
                        relations.append(
                            {
                                "source": source,
                                "target": target,
                                "relation": relation_type,
                                "confidence": 0.72,
                                "context": match.group().strip(),
                            }
                        )
        return relations

    def _find_entity(self, fragment: str, entities: List[Dict[str, Any]]) -> Optional[Dict[str, Any]]:
        fragment = fragment.strip()
        for entity in entities:
            if entity["text"] in fragment or fragment in entity["text"]:
                return entity
        return None


class KnowledgeGraphBuilder:
    def __init__(self) -> None:
        self.entity_extractor = EntityExtractor()
        self.relation_extractor = RelationExtractor()
        self.driver = self._init_neo4j()
        self.graph = nx.DiGraph()

    def _init_neo4j(self):
        if not GraphDatabase or not NEO4J_CONFIG.get("password"):
            return None
        driver = None
        try:
            driver = GraphDatabase.driver(
                NEO4J_CONFIG["uri"],
                auth=(NEO4J_CONFIG["user"], NEO4J_CONFIG["password"]),
                connection_timeout=NEO4J_CONFIG.get("timeout", 3),
            )
            driver.verify_connectivity()
            return driver
        except Exception as exc:
            logger.info("Neo4j unavailable for graph builder: %s", exc)
            if driver:
                driver.close()
            return None

    def close(self) -> None:
        if self.driver:
            self.driver.close()

    def build_from_text(self, text: str, language: str = "auto") -> Dict[str, Any]:
        entities = self.entity_extractor.extract_entities(text, language)
        relations = self.relation_extractor.extract_relations(text, entities)
        self._build_networkx_graph(entities, relations)
        if self.driver:
            self._store_to_neo4j(entities, relations)
        return {
            "entities": entities,
            "relations": relations,
            "graph_stats": {"nodes": self.graph.number_of_nodes(), "edges": self.graph.number_of_edges()},
            "neo4j_enabled": bool(self.driver),
        }

    def _build_networkx_graph(self, entities: List[Dict[str, Any]], relations: List[Dict[str, Any]]) -> None:
        for entity in entities:
            self.graph.add_node(entity["text"], label=entity["label"], confidence=entity["confidence"])
        for relation in relations:
            self.graph.add_edge(
                relation["source"]["text"],
                relation["target"]["text"],
                relation=relation["relation"],
                confidence=relation["confidence"],
                context=relation["context"],
            )

    def _store_to_neo4j(self, entities: List[Dict[str, Any]], relations: List[Dict[str, Any]]) -> None:
        try:
            with self.driver.session() as session:
                for entity in entities:
                    session.run(
                        """
                        MERGE (e:AuditEntity {text: $text})
                        SET e.label = $label,
                            e.confidence = $confidence,
                            e.updated_at = datetime()
                        """,
                        text=entity["text"],
                        label=entity["label"],
                        confidence=entity["confidence"],
                    )
                for relation in relations:
                    session.run(
                        """
                        MATCH (source:AuditEntity {text: $source_text})
                        MATCH (target:AuditEntity {text: $target_text})
                        MERGE (source)-[r:RELATES_TO {type: $relation_type}]->(target)
                        SET r.confidence = $confidence,
                            r.context = $context,
                            r.updated_at = datetime()
                        """,
                        source_text=relation["source"]["text"],
                        target_text=relation["target"]["text"],
                        relation_type=relation["relation"],
                        confidence=relation["confidence"],
                        context=relation["context"],
                    )
        except Exception as exc:
            logger.warning("Failed to persist graph to Neo4j: %s", exc)

    def build_from_documents(self, documents: List[str], language: str = "auto") -> Dict[str, Any]:
        all_entities: List[Dict[str, Any]] = []
        all_relations: List[Dict[str, Any]] = []
        for text in documents:
            result = self.build_from_text(text, language)
            all_entities.extend(result["entities"])
            all_relations.extend(result["relations"])
        return {
            "entities": all_entities,
            "relations": all_relations,
            "graph_stats": {"nodes": self.graph.number_of_nodes(), "edges": self.graph.number_of_edges()},
            "neo4j_enabled": bool(self.driver),
        }

    def query_graph(self, query: str) -> List[Dict[str, Any]]:
        if self.driver:
            with self.driver.session() as session:
                records = session.run(
                    """
                    MATCH (n:AuditEntity)-[r]->(m:AuditEntity)
                    WHERE n.text CONTAINS $query OR m.text CONTAINS $query
                    RETURN n.text AS source, r.type AS relation, m.text AS target, r.context AS context
                    LIMIT 50
                    """,
                    query=query,
                )
                return [dict(record) for record in records]

        results = []
        for source, target, data in self.graph.edges(data=True):
            if query in source or query in target or query in data.get("context", ""):
                results.append({"source": source, "relation": data.get("relation"), "target": target, "context": data.get("context")})
        return results

    def get_graph_statistics(self) -> Dict[str, Any]:
        return {
            "nodes": self.graph.number_of_nodes(),
            "edges": self.graph.number_of_edges(),
            "neo4j_enabled": bool(self.driver),
        }

import secrets
import uuid

from fastapi import APIRouter, Depends, HTTPException

from api.deps import get_current_active_user, get_api_key_db
from api.schemas import (
    ApiKeyCreateRequest,
    ApiKeyCreatedResponse,
    ApiKeyDeleteResponse,
    ApiKeyListResponse,
    ErrorResponse,
)
from core.auth import get_password_hash_str
from db import ApiKeyDB

router = APIRouter(prefix="/api-keys", tags=["api-keys"])


@router.get(
    "",
    summary="List API keys for the current user",
    responses={
        200: {"model": ApiKeyListResponse, "description": "List of API keys"},
    },
)
def list_api_keys(
    current_user: dict = Depends(get_current_active_user),
    db: ApiKeyDB = Depends(get_api_key_db),
):
    """Return all API keys belonging to the authenticated user (without hashes)."""
    keys = db.list_keys_for_user(current_user["uuid"])
    return {"api_keys": keys}


@router.post(
    "",
    status_code=201,
    summary="Create an API key",
    responses={
        201: {"model": ApiKeyCreatedResponse, "description": "API key created (raw key shown once)"},
    },
)
def create_api_key(
    payload: ApiKeyCreateRequest,
    current_user: dict = Depends(get_current_active_user),
    db: ApiKeyDB = Depends(get_api_key_db),
):
    """Generate a new API key for the authenticated user.

    The raw key is returned exactly once in this response and is never stored.
    """
    MAX_KEYS_PER_USER = 25
    existing_keys = db.list_keys_for_user(current_user["uuid"])
    if len(existing_keys) >= MAX_KEYS_PER_USER:
        raise HTTPException(status_code=400, detail=f"Maximum of {MAX_KEYS_PER_USER} API keys per user reached")

    raw_key = secrets.token_urlsafe(48)
    key_id = str(uuid.uuid4())

    record = db.insert_api_key({
        "id": key_id,
        "user_uuid": current_user["uuid"],
        "name": payload.name,
        "key_hash": get_password_hash_str(raw_key),
        "prefix": raw_key[:8],
    })

    # Fetch the full row to get the DB-generated created_at timestamp
    full_record = db.get_key(key_id)
    return {
        **record,
        "raw_key": raw_key,
        "created_at": full_record["created_at"] if full_record else None,
    }


@router.delete(
    "/{key_id}",
    summary="Delete an API key",
    responses={
        200: {"model": ApiKeyDeleteResponse, "description": "API key deleted"},
        404: {"model": ErrorResponse, "description": "API key not found"},
    },
)
def delete_api_key(
    key_id: str,
    current_user: dict = Depends(get_current_active_user),
    db: ApiKeyDB = Depends(get_api_key_db),
):
    """Delete one of the authenticated user's API keys."""
    if not db.delete_key(key_id, current_user["uuid"]):
        raise HTTPException(status_code=404, detail="API key not found")
    return {"message": "API key deleted successfully"}

"""Shared helpers for reading the Astro CLI's user session on disk.

Both ``astro_pat`` (resolves a bearer for httpx) and
``discovery.astro_cli`` (reads the active context to label discovered
deployments) need the same primitives: where ``~/.astro/config.yaml``
lives, how to parse it, how to find the active context, how to compute
expiry. Hosting them here lets the auth side and the discovery side
share one canonical source without one importing the other's privates.

Names start with an underscore to signal "internal to astro-airflow-mcp".
``astro_pat`` re-exports them for backward compatibility with tests that
already import from there.
"""

from __future__ import annotations

import os
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import yaml

_AUTH_CONFIG_PATH = "private/v1alpha1/cli/auth-config"


class AstroPATError(Exception):
    """Base class for errors reading or refreshing the astro CLI session.

    Lives here (rather than under ``astro_pat``) so this module has no
    upward dependency. ``astro_pat`` re-exports it; existing
    ``except AstroPATError`` call sites keep working.
    """


class AstroNotLoggedInError(AstroPATError):
    """No usable session in ~/.astro/config.yaml: user needs ``astro login``."""


def _astro_home() -> Path:
    return Path(os.environ.get("ASTRO_HOME") or (Path.home() / ".astro"))


def _config_path() -> Path:
    return _astro_home() / "config.yaml"


def _read_yaml(path: Path) -> dict[str, Any]:
    """Read and parse the astro config. Empty/missing/non-file → {}.

    Treats "missing or not-a-regular-file" as "no astro session" (path is
    absent, ASTRO_HOME points at /dev/null or a directory, etc). Other
    OSError shapes (PermissionError, IOError) are deliberately not
    swallowed — those mean a real config exists but isn't readable, and
    surfacing the error is more useful than a misleading "run astro
    login" downstream.
    """
    try:
        text = path.read_text()
    except (FileNotFoundError, NotADirectoryError, IsADirectoryError):
        return {}
    try:
        return yaml.safe_load(text) or {}
    except yaml.YAMLError:
        # Astro CLI rewrites this file in place (truncate+write under flock).
        # If we happen to read mid-write we get a partial document. One short
        # retry catches the race; if it persists, surface as empty (caller
        # decides whether that means "log in" or "use env var fallback").
        time.sleep(0.05)
        try:
            return yaml.safe_load(path.read_text()) or {}
        except (FileNotFoundError, NotADirectoryError, IsADirectoryError, yaml.YAMLError):
            return {}


def _context_key(domain: str) -> str:
    """Key under which astro CLI stores `domain`'s context (dots → underscores)."""
    return domain.replace(".", "_")


def _find_context(cfg: dict[str, Any], domain: str | None) -> tuple[str, dict[str, Any]]:
    """Locate (domain, context_dict) by domain or by active context.

    astro CLI keys contexts by domain with dots replaced by underscores
    (``astronomer.io`` → ``astronomer_io``). Some context dicts don't carry
    an explicit ``domain`` field, so the keyed lookup is the canonical path
    and we fall back to scanning ``ctx.domain`` only for older configs.
    """
    contexts = cfg.get("contexts") or {}
    target = domain or cfg.get("context")
    if not target:
        raise AstroNotLoggedInError("No active astro context. Run `astro login` to authenticate.")
    ctx = contexts.get(_context_key(target))
    if ctx:
        return target, ctx
    # Backward-compat fallback for contexts that DO carry a `domain` field.
    for c in contexts.values():
        if c and c.get("domain") == target:
            return target, c
    raise AstroNotLoggedInError(f"No astro context for domain {target!r}. Run `astro login` first.")


def _auth_config_url(domain: str) -> str:
    """URL of the per-domain auth-config endpoint.

    Mirrors ``pkg/domainutil/domain.go::GetURLToEndpoint`` in astro-cli:
    plain domain → ``api.<domain>``, PR-preview ``prNNN.astronomer-dev.io``
    → ``prNNN.api.astronomer-dev.io``, and ``localhost`` → port 8888.
    """
    if domain == "localhost":
        return f"http://localhost:8888/{_AUTH_CONFIG_PATH}"
    head, _, rest = domain.partition(".")
    if head.startswith("pr") and rest:
        return f"https://{head}.api.{rest}/{_AUTH_CONFIG_PATH}"
    return f"https://api.{domain}/{_AUTH_CONFIG_PATH}"


def _parse_expiry(ctx: dict[str, Any]) -> float:
    """Return token expiry as epoch seconds. 0 if unknown.

    astro CLI (via viper) writes ``expiresin`` as a tz-aware ISO timestamp
    with the local offset (eg ``2026-05-01T16:48:36+01:00``). We anchor
    naive datetimes to UTC as defense-in-depth in case a user hand-edits
    the file or another writer drops the offset, since ``.timestamp()``
    would otherwise interpret naive values as local time.
    """
    expiresin = ctx.get("expiresin")
    if isinstance(expiresin, str):
        try:
            dt = datetime.fromisoformat(expiresin)
        except ValueError:
            return 0.0
    elif isinstance(expiresin, datetime):
        # PyYAML parses unquoted ISO timestamps as datetime when possible.
        dt = expiresin
    else:
        return 0.0
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.timestamp()


def _bearer_from_ctx(ctx: dict[str, Any]) -> str:
    raw = ctx.get("token") or ""
    return raw.removeprefix("Bearer ").strip()

import os
import sys

import yaml

TEMPLATES_DIR = ".github/ISSUE_TEMPLATE"
LABELS_FILE = ".github/labels.yml"


def get_live_labels():
    with open(LABELS_FILE) as f:
        data = yaml.safe_load(f)
    labels = set()
    for group in data.values():
        if isinstance(group, list):
            for item in group:
                if isinstance(item, str):
                    labels.add(item)
    return labels


def get_template_labels():
    used = {}
    for fname in os.listdir(TEMPLATES_DIR):
        if not fname.endswith(".yml"):
            continue
        path = os.path.join(TEMPLATES_DIR, fname)
        with open(path) as f:
            data = yaml.safe_load(f)
        if isinstance(data.get("labels"), list):
            used[fname] = data["labels"]
    return used


def main():
    live = get_live_labels()
    templates = get_template_labels()
    errors = []

    for fname, labels in templates.items():
        for label in labels:
            if label not in live:
                errors.append(f"  [{fname}] unknown label: '{label}'")

    if errors:
        print("Label mismatch found:")
        for e in errors:
            print(e)
        sys.exit(1)
    else:
        print("All template labels match live taxonomy.")


if __name__ == "__main__":
    main()

