dexbotic_data_path = os.getenv('DEXBOTIC_DATA_PATH', None)
if dexbotic_data_path:
    import_modules_from_directory(dexbotic_data_path, is_external=True)

"""Deterministic aggregation of stored DOCSIS snapshots."""

from __future__ import annotations

import hashlib
import json
import math
from collections.abc import Mapping, Sequence
from typing import Any

from app.analyzer import resolve_snr_thresholds
from app.docsis_utils import classify_channel_family

from .contract import (
    AGGREGATION_SCHEMA_VERSION,
    Coverage,
    PeriodAggregate,
    ThresholdContext,
    Window,
)
from .provenance import aggregate_provenance, derive_historical
from .window import canonical_utc_timestamp

_AVERAGE_FIELDS = {
    "ds_power": "ds_power_avg",
    "ds_snr": "ds_snr_avg",
    "us_power": "us_power_avg",
}
_RAW_WORST_FIELDS = {
    "ds_power_max": "ds_power_max",
    "ds_power_min": "ds_power_min",
    "us_power_max": "us_power_max",
    "ds_snr_min": "ds_snr_min",
    "ds_uncorrectable_max": "ds_uncorrectable_errors",
    "ds_correctable_max": "ds_correctable_errors",
}
_COUNTER_FIELDS = {"ds_uncorrectable_max", "ds_correctable_max"}
_WORST_FIELDS = (*_RAW_WORST_FIELDS, "ds_snr_warn_min")


def _content_digest(snapshot: Mapping[str, Any]) -> str:
    payload = json.dumps(
        snapshot,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _ordered_snapshots(
    snapshots: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    return sorted(
        snapshots,
        key=lambda snapshot: (
            canonical_utc_timestamp(snapshot.get("timestamp")),
            _content_digest(snapshot),
        ),
    )


def _number(value: Any) -> float | None:
    if isinstance(value, bool):
        return None
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return None
    return parsed if math.isfinite(parsed) else None


def _empty_coverage(total: int) -> Coverage:
    return {
        "samples": 0,
        "nulls": 0,
        "unsupported": 0,
        "invalid": 0,
        "missing": 0,
        "total": total,
    }


def _full_coverage(total: int) -> Coverage:
    coverage = _empty_coverage(total)
    coverage["samples"] = total
    return coverage


def _value_state(
    values: Mapping[str, Any], key: str, *, unsupported: bool = False
) -> str:
    if unsupported:
        return "unsupported"
    if key not in values:
        return "missing"
    value = values[key]
    if value is None:
        return "nulls"
    return "samples" if _number(value) is not None else "invalid"


def _snr_warning_threshold(
    snapshot: Mapping[str, Any], numeric_snr: float, thresholds: ThresholdContext
) -> tuple[str, Any]:
    """Classify a derived threshold without treating its source SNR as a sample.

    Null/invalid/absent source SNR states are propagated by the caller. A valid
    source is counted as a derived sample only when a matching channel yields a
    finite warning threshold; otherwise the derived value is missing/invalid.
    """
    for channel in snapshot.get("ds_channels") or []:
        if not isinstance(channel, Mapping) or _number(channel.get("snr")) != numeric_snr:
            continue
        family = channel.get("channel_family") or classify_channel_family("ds", channel)
        spec = resolve_snr_thresholds(
            channel.get("modulation"),
            channel_family=family,
            thresholds=thresholds.raw,
        )
        raw_warning = spec.get("warn_min")
        if _number(raw_warning) is not None:
            return "samples", raw_warning
        return "invalid", None
    return "missing", None


def _bad_channels(
    ordered: Sequence[Mapping[str, Any]], direction: str
) -> list[tuple[Any, int]]:
    counts: dict[Any, int] = {}
    key = "ds_channels" if direction == "ds" else "us_channels"
    for snapshot in ordered:
        for channel in snapshot.get(key) or []:
            if channel.get("health") in ("good", "tolerated"):
                continue
            channel_id = channel.get("channel_id", 0)
            counts[channel_id] = counts.get(channel_id, 0) + 1
    return sorted(counts.items(), key=lambda item: item[1], reverse=True)[:5]


def aggregate_snapshot_period(
    snapshots: Sequence[Mapping[str, Any]],
    *,
    window: Window,
    thresholds: ThresholdContext,
) -> PeriodAggregate:
    """Aggregate stored snapshots deterministically within inclusive UTC bounds.

    The caller owns storage filtering. This pure function preserves duplicate
    multiplicity, orders equal timestamps by a content digest, keeps semantic
    nulls distinct from numeric zero, and never mutates snapshots or thresholds.
    """
    ordered = _ordered_snapshots(list(snapshots or []))
    total = len(ordered)
    worst: dict[str, Any] = {
        "ds_power_max": None,
        "ds_power_min": None,
        "us_power_max": None,
        "ds_snr_min": None,
        "ds_snr_warn_min": None,
        "ds_uncorrectable_max": None,
        "ds_correctable_max": None,
        "health_critical_count": 0,
        "health_marginal_count": 0,
        "health_tolerated_count": 0,
        "total_snapshots": total,
    }
    metric_coverage = {
        key: _empty_coverage(total)
        for key in (*_AVERAGE_FIELDS, *_WORST_FIELDS)
    }
    average_values: dict[str, list[float]] = {
        "ds_power": [],
        "ds_snr": [],
        "us_power": [],
    }
    counter_totals = {"ds_correctable_errors": 0, "ds_uncorrectable_errors": 0}
    counter_supported = {"ds_correctable_errors": False, "ds_uncorrectable_errors": False}
    health_distribution: dict[Any, int] = {}
    samples: list[dict[str, Any]] = []

    for snapshot in ordered:
        raw_summary = snapshot.get("summary")
        summary = raw_summary if isinstance(raw_summary, Mapping) else {}
        errors_supported = bool(summary.get("errors_supported", True))

        for output_key, summary_key in _AVERAGE_FIELDS.items():
            state = _value_state(summary, summary_key)
            metric_coverage[output_key][state] += 1
        for output_key, summary_key in _RAW_WORST_FIELDS.items():
            state = _value_state(
                summary,
                summary_key,
                unsupported=output_key in _COUNTER_FIELDS and not errors_supported,
            )
            metric_coverage[output_key][state] += 1

        snr_source_state = _value_state(summary, "ds_snr_min")
        derived_warning = None
        if snr_source_state == "samples":
            numeric_snr = _number(summary.get("ds_snr_min"))
            assert numeric_snr is not None
            warning_state, derived_warning = _snr_warning_threshold(
                snapshot, numeric_snr, thresholds
            )
        else:
            warning_state = snr_source_state
        metric_coverage["ds_snr_warn_min"][warning_state] += 1

        health = summary.get("health", "unknown")
        health_distribution[health] = health_distribution.get(health, 0) + 1
        if health == "critical":
            worst["health_critical_count"] += 1
        elif health == "marginal":
            worst["health_marginal_count"] += 1
        elif health == "tolerated":
            worst["health_tolerated_count"] += 1

        for output_key, summary_key in _AVERAGE_FIELDS.items():
            value = _number(summary.get(summary_key))
            if value is not None:
                average_values[output_key].append(value)

        for key in ("ds_power_max", "ds_power_min"):
            raw = summary.get(key)
            numeric = _number(raw)
            if numeric is None:
                continue
            current = worst[key]
            if current is None or abs(numeric) > abs(float(current)):
                worst[key] = raw

        raw = summary.get("us_power_max")
        numeric = _number(raw)
        if numeric is not None:
            current = _number(worst["us_power_max"])
            if current is None or numeric > current:
                worst["us_power_max"] = raw

        raw_snr = summary.get("ds_snr_min")
        numeric_snr = _number(raw_snr)
        if numeric_snr is not None:
            current_snr = _number(worst["ds_snr_min"])
            if current_snr is None or numeric_snr < current_snr:
                worst["ds_snr_min"] = raw_snr
                worst["ds_snr_warn_min"] = None
            if (
                numeric_snr == _number(worst["ds_snr_min"])
                and worst["ds_snr_warn_min"] is None
                and derived_warning is not None
            ):
                worst["ds_snr_warn_min"] = derived_warning

        for summary_key, worst_key in (
            ("ds_uncorrectable_errors", "ds_uncorrectable_max"),
            ("ds_correctable_errors", "ds_correctable_max"),
        ):
            raw_counter = summary.get(summary_key) if errors_supported else None
            numeric_counter = _number(raw_counter)
            if numeric_counter is None:
                continue
            current = _number(worst[worst_key])
            if current is None or numeric_counter > current:
                worst[worst_key] = raw_counter
            counter_supported[summary_key] = True
            counter_totals[summary_key] += (
                raw_counter
                if isinstance(raw_counter, (int, float)) and not isinstance(raw_counter, bool)
                else numeric_counter
            )

        uncorr = summary.get("ds_uncorrectable_errors") if errors_supported else None
        if _number(uncorr) is None:
            uncorr = None
        samples.append({
            "timestamp": canonical_utc_timestamp(snapshot.get("timestamp")),
            "ds_power_avg": summary.get("ds_power_avg") if _number(summary.get("ds_power_avg")) is not None else None,
            "ds_snr_avg": summary.get("ds_snr_avg") if _number(summary.get("ds_snr_avg")) is not None else None,
            "us_power_avg": summary.get("us_power_avg") if _number(summary.get("us_power_avg")) is not None else None,
            "uncorr_errors": uncorr,
            "health": health,
        })

    historical = derive_historical(ordered, thresholds=thresholds)
    metric_coverage.update({
        "health_critical_count": _full_coverage(total),
        "health_marginal_count": _full_coverage(total),
        "health_tolerated_count": _full_coverage(total),
        "total_snapshots": _full_coverage(total),
    })
    return {
        "schema_version": AGGREGATION_SCHEMA_VERSION,
        "window": {"start": window.start, "end": window.end},
        "snapshot_count": total,
        "first_observed_at": samples[0]["timestamp"] if samples else None,
        "last_observed_at": samples[-1]["timestamp"] if samples else None,
        "latest_snapshot": ordered[-1] if ordered else None,
        "provenance": aggregate_provenance(ordered, thresholds=thresholds),
        "health_distribution": health_distribution,
        "worst": worst,
        "metric_coverage": metric_coverage,
        "averages": {
            key: (sum(values) / len(values) if values else None)
            for key, values in average_values.items()
        },
        "totals": {
            "ds_correctable_errors": (
                counter_totals["ds_correctable_errors"]
                if counter_supported["ds_correctable_errors"] else None
            ),
            "ds_uncorrectable_errors": (
                counter_totals["ds_uncorrectable_errors"]
                if counter_supported["ds_uncorrectable_errors"] else None
            ),
            "correctable_supported": counter_supported["ds_correctable_errors"],
            "uncorrectable_supported": counter_supported["ds_uncorrectable_errors"],
            "errors_supported": any(counter_supported.values()),
        },
        "worst_channels": {
            "ds": _bad_channels(ordered, "ds"),
            "us": _bad_channels(ordered, "us"),
        },
        "samples": samples,
        "diagnostic_notes": historical["diagnostic_notes"],
    }

#!/usr/bin/env python3
"""Extract structured text from a LaTeX project or PDF manuscript.

Usage:
    python extract_manuscript_text.py --input PATH --output manuscript.json

PATH may be a directory containing .tex files, a single .tex file, or a .pdf file.

Output JSON schema (see references/report_template.md for downstream consumers):
{
  "source_type": "latex" | "pdf",
  "root_files": [...],
  "raw_text": "<concatenated body text>",
  "sections": [{"title": "...", "level": 1, "line": 12, "file": "main.tex"}],
  "figures":  [{"label": "...", "line": ..., "file": "..."}],
  "tables":   [{"label": "...", "line": ..., "file": "..."}],
  "cite_keys":   [{"key": "smith2024", "line": ..., "file": "..."}],
  "label_defs":  [{"label": "fig:foo", "line": ..., "file": "..."}],
  "label_refs":  [{"label": "fig:foo", "line": ..., "file": "..."}],
  "numbers":     [{"value": "92.3", "context": "achieves 92.3% accuracy", "line": ..., "file": "..."}],
  "warnings": [...]
}

Stdlib only. PDF path uses `pdftotext` if available; otherwise reports a warning.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path
from typing import Iterable

if sys.version_info < (3, 9):
    raise SystemExit(f"arxiv-preflight requires Python 3.9+; got {sys.version.split()[0]}")

INPUT_INCLUDE_RE = re.compile(r"\\(?:input|include|subfile)\{([^}]+)\}")
SECTION_RE = re.compile(r"\\(part|chapter|section|subsection|subsubsection|paragraph)\*?\{([^}]*)\}")
LEVEL = {"part": 0, "chapter": 1, "section": 1, "subsection": 2, "subsubsection": 3, "paragraph": 4}
FIGURE_BEGIN = re.compile(r"\\begin\{figure\*?\}")
TABLE_BEGIN = re.compile(r"\\begin\{table\*?\}")
LABEL_RE = re.compile(r"\\label\{([^}]+)\}")
REF_RE = re.compile(r"\\(?:ref|eqref|autoref|cref|Cref)\{([^}]+)\}")
CITE_RE = re.compile(r"\\(?:cite|citep|citet|citeauthor|citeyear|parencite|textcite)\*?(?:\[[^\]]*\])?(?:\[[^\]]*\])?\{([^}]+)\}")
COMMENT_RE = re.compile(r"(?<!\\)%.*?$", re.MULTILINE)
VERBATIM_BLOCK_RE = re.compile(
    r"\\begin\{(verbatim|lstlisting|minted|alltt)\*?\}.*?\\end\{\1\*?\}",
    re.DOTALL,
)
# A "number in context" — keep ≤ 30 surrounding chars before, ≤ 60 after, with a unit hint.
NUMBER_RE = re.compile(
    r"(?P<pre>.{0,30})\b(?P<num>\d+(?:\.\d+)?)(?P<unit>\s?%|\s?(?:percent|points?|ms|s|sec(?:onds)?|x|×|fold|dB|GB|MB|TB|Hz|FLOPs?))?(?P<post>.{0,60})",
    re.IGNORECASE,
)


def strip_comments_and_verbatim(text: str) -> str:
    """Remove LaTeX line comments and verbatim/code blocks.

    Returns a string with the same line count so downstream line numbers stay valid.
    """
    def blank_keeping_lines(m: re.Match) -> str:
        return "\n" * m.group(0).count("\n")

    text = VERBATIM_BLOCK_RE.sub(blank_keeping_lines, text)
    text = COMMENT_RE.sub("", text)
    return text


def discover_root_tex(root: Path) -> list[Path]:
    """Pick likely entry files: those that contain \\documentclass."""
    candidates: list[Path] = []
    for tex in root.rglob("*.tex"):
        try:
            head = tex.read_text(encoding="utf-8", errors="replace")[:4000]
        except Exception:
            continue
        if "\\documentclass" in head:
            candidates.append(tex)
    return candidates or sorted(root.rglob("*.tex"))[:1]


def resolve_include(parent: Path, target: str) -> Path | None:
    candidate = (parent.parent / target).resolve()
    if candidate.suffix == "":
        candidate = candidate.with_suffix(".tex")
    if candidate.exists():
        return candidate
    return None


def walk_tex(root_tex: Path, project_root: Path, seen: set[Path], warnings: list[str]) -> Iterable[tuple[Path, str]]:
    """Yield (file_path, raw_text_with_includes_inlined_as_marker) in include order.

    We do not actually inline file contents into one stream — downstream consumers
    want per-file line numbers. We yield each file individually.
    """
    if root_tex in seen:
        return
    seen.add(root_tex)
    try:
        text = root_tex.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return
    yield root_tex, text
    for match in INPUT_INCLUDE_RE.finditer(text):
        include_target = match.group(1)
        child = resolve_include(root_tex, include_target)
        if not child:
            warnings.append(f"{root_tex}: unresolved include `{include_target}`")
            continue
        if not child.is_relative_to(project_root):
            warnings.append(f"{root_tex}: skipped include `{include_target}` outside project root: {child}")
            continue
        yield from walk_tex(child, project_root, seen, warnings)


def _line_no(text: str, offset: int) -> int:
    return text.count("\n", 0, offset) + 1


def parse_latex_file(path: Path, text: str) -> dict:
    """Run all extractors on the whole cleaned text.

    Line-by-line scanning loses citations and refs that span lines
    (e.g., `\\cite{a,\\n b}`); scan whole-text and back-resolve line numbers.
    """
    cleaned = strip_comments_and_verbatim(text)
    sections, figures, tables = [], [], []
    cite_keys, label_defs, label_refs, numbers = [], [], [], []
    file_str = str(path)

    for m in SECTION_RE.finditer(cleaned):
        sections.append({
            "title": m.group(2).strip(),
            "level": LEVEL.get(m.group(1), 5),
            "line": _line_no(cleaned, m.start()),
            "file": file_str,
        })
    for m in LABEL_RE.finditer(cleaned):
        label = m.group(1)
        ln = _line_no(cleaned, m.start())
        label_defs.append({"label": label, "line": ln, "file": file_str})
        if label.startswith("fig:"):
            figures.append({"label": label, "line": ln, "file": file_str})
        elif label.startswith("tab:") or label.startswith("table:"):
            tables.append({"label": label, "line": ln, "file": file_str})
    for m in REF_RE.finditer(cleaned):
        ln = _line_no(cleaned, m.start())
        for label in m.group(1).split(","):
            label_refs.append({"label": label.strip(), "line": ln, "file": file_str})
    for m in CITE_RE.finditer(cleaned):
        ln = _line_no(cleaned, m.start())
        for key in m.group(1).split(","):
            key = key.strip()
            if key:
                cite_keys.append({"key": key, "line": ln, "file": file_str})
    # Numbers run line-by-line because the context window is line-local anyway.
    for idx, line in enumerate(cleaned.splitlines(), start=1):
        for m in NUMBER_RE.finditer(line):
            unit = (m.group("unit") or "").strip()
            if not unit and not _looks_like_metric(line):
                continue
            numbers.append({
                "value": m.group("num"),
                "unit": unit,
                "context": (m.group("pre") + m.group("num") + (m.group("unit") or "") + m.group("post")).strip(),
                "line": idx,
                "file": file_str,
            })
    return {
        "sections": sections,
        "figures": figures,
        "tables": tables,
        "cite_keys": cite_keys,
        "label_defs": label_defs,
        "label_refs": label_refs,
        "numbers": numbers,
        "raw_text": cleaned,
    }


def _looks_like_metric(line: str) -> bool:
    return bool(re.search(r"\b(accuracy|f1|bleu|rouge|recall|precision|mse|rmse|mae|auc|auroc|aupr|loss|perplexity|map|ndcg|wer|cer)\b", line, re.IGNORECASE))


def extract_latex(input_path: Path) -> dict:
    if input_path.is_file():
        roots = [input_path.resolve()]
        project_root = input_path.parent.resolve()
    else:
        project_root = input_path.resolve()
        roots = [p.resolve() for p in discover_root_tex(project_root)]
    if not roots:
        return {"source_type": "latex", "warnings": ["no .tex files discovered"], "raw_text": ""}
    aggregated = {
        "source_type": "latex",
        "root_files": [str(p) for p in roots],
        "raw_text": "",
        "sections": [], "figures": [], "tables": [],
        "cite_keys": [], "label_defs": [], "label_refs": [], "numbers": [],
        "warnings": [],
    }
    seen: set[Path] = set()
    for root in roots:
        for path, text in walk_tex(root, project_root, seen, aggregated["warnings"]):
            parsed = parse_latex_file(path, text)
            aggregated["raw_text"] += f"\n%%FILE {path}\n" + parsed.pop("raw_text")
            for key in ["sections", "figures", "tables", "cite_keys", "label_defs", "label_refs", "numbers"]:
                aggregated[key].extend(parsed[key])
    return aggregated


def extract_pdf(input_path: Path) -> dict:
    if not shutil.which("pdftotext"):
        return {
            "source_type": "pdf",
            "raw_text": "",
            "warnings": [
                "pdftotext not available; install poppler (`brew install poppler` / `apt install poppler-utils`)"
                " or pass the LaTeX source instead — PDF reference checks are less reliable."
            ],
            "sections": [], "figures": [], "tables": [],
            "cite_keys": [], "label_defs": [], "label_refs": [], "numbers": [],
        }
    try:
        out = subprocess.run(
            ["pdftotext", "-layout", str(input_path), "-"],
            capture_output=True, text=True, timeout=60, check=True,
        )
    except subprocess.CalledProcessError as e:
        return {"source_type": "pdf", "raw_text": "", "warnings": [f"pdftotext failed: {e}"]}
    text = out.stdout
    numbers = []
    for idx, line in enumerate(text.splitlines(), start=1):
        for m in NUMBER_RE.finditer(line):
            unit = (m.group("unit") or "").strip()
            if not unit and not _looks_like_metric(line):
                continue
            numbers.append({
                "value": m.group("num"),
                "unit": unit,
                "context": line.strip()[:140],
                "line": idx,
                "file": str(input_path),
            })
    return {
        "source_type": "pdf",
        "root_files": [str(input_path)],
        "raw_text": f"\n%%FILE {input_path.resolve()}\n{text}",
        "sections": [], "figures": [], "tables": [],
        "cite_keys": [], "label_defs": [], "label_refs": [],
        "numbers": numbers,
        "warnings": ["PDF input — section/cite/label structure not recovered; supply LaTeX source for full checks."],
    }


def main() -> int:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--input", required=True, type=Path)
    p.add_argument("--output", type=Path, default=Path("manuscript.json"))
    args = p.parse_args()

    if not args.input.exists():
        print(f"error: {args.input} does not exist", file=sys.stderr)
        return 2
    if args.input.suffix.lower() == ".pdf":
        result = extract_pdf(args.input)
    else:
        result = extract_latex(args.input)
    args.output.write_text(json.dumps(result, indent=2, ensure_ascii=False))
    print(f"wrote {args.output} ({len(result.get('raw_text', ''))} chars, "
          f"{len(result.get('sections', []))} sections, "
          f"{len(result.get('cite_keys', []))} citations)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

