    alphabet = Alphabet(**config['alphabet'])

    if alphabet.get_idx(MASK_TKN) != config['globals'].mask_tkn_idx:
        return True

    if alphabet.get_idx(PAD_TKN) != config['globals'].pad_tkn_idx:
        return True

    if len(alphabet) != config['globals'].alphabet_size:
        return True

    return False

