#!/usr/bin/env python3
"""Generate a slim wire-contract file from the pfSense REST API OpenAPI spec.

The upstream `openapi.json` (a release asset of pfrest/pfSense-pkg-RESTAPI) is
~4 MB. This distills it to just what a payload contract test needs: for every
writable endpoint, the set of valid field names, their JSON types, any enum
choices, and which fields are required on create (POST) vs update (PATCH).

Usage:
    python generate_contract.py openapi.json contract-v2.10.2.json --version v2.10.2
"""
import argparse
import json
import sys


def _resolve_ref(ref, root):
    node = root
    for part in ref.lstrip("#/").split("/"):
        node = node[part]
    return node


def _field_spec(prop):
    """Distill an OpenAPI property node to {type, items, enum}."""
    spec = {"type": prop.get("type")}
    if "items" in prop and isinstance(prop["items"], dict):
        spec["items"] = prop["items"].get("type")
    if "enum" in prop:
        spec["enum"] = prop["enum"]
    # nullable/anyOf: capture the non-null branch's type if the top-level type is absent
    if spec["type"] is None and "anyOf" in prop:
        types = [b.get("type") for b in prop["anyOf"] if b.get("type") not in (None, "null")]
        if types:
            spec["type"] = types[0]
    return spec


def _merge_schema(schema, root):
    """Resolve $ref/allOf into a flat {properties, required} dict."""
    properties = {}
    required = []
    if "$ref" in schema:
        schema = _resolve_ref(schema["$ref"], root)
    if "allOf" in schema:
        for sub in schema["allOf"]:
            merged = _merge_schema(sub, root)
            properties.update(merged["properties"])
            required.extend(merged["required"])
        return {"properties": properties, "required": required}
    for name, prop in schema.get("properties", {}).items():
        properties[name] = _field_spec(prop)
    required.extend(schema.get("required", []))
    return {"properties": properties, "required": required}


def _request_schema(operation, root):
    body = operation.get("requestBody", {})
    content = body.get("content", {})
    media = content.get("application/json") or next(iter(content.values()), None)
    if not media or "schema" not in media:
        return None
    return _merge_schema(media["schema"], root)


def build(spec):
    root = spec
    contract = {}
    for path, methods in spec["paths"].items():
        for method in ("post", "patch"):
            if method not in methods:
                continue
            merged = _request_schema(methods[method], root)
            if merged is None:
                continue
            contract[f"{method.upper()} {path}"] = {
                "properties": merged["properties"],
                "required": sorted(set(merged["required"])),
            }
        # GET: model properties are the valid query-filter fields
        if "get" in methods:
            # The GET response schema references the same model; capture its fields
            # from the sibling POST/PATCH if present, else skip (queries validated
            # against the writable contract in practice).
            pass
    return contract


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("openapi")
    ap.add_argument("out")
    ap.add_argument("--version", required=True)
    args = ap.parse_args()
    spec = json.load(open(args.openapi))
    contract = build(spec)
    out = {
        "_meta": {
            "source": "pfrest/pfSense-pkg-RESTAPI openapi.json",
            "pkg_restapi_version": args.version,
            "endpoint_count": len(contract),
        },
        "endpoints": contract,
    }
    json.dump(out, open(args.out, "w"), indent=1, sort_keys=True)
    print(f"wrote {args.out}: {len(contract)} endpoints", file=sys.stderr)


if __name__ == "__main__":
    main()

import streamlit as st
import pandas as pd
from sklearn.preprocessing import LabelEncoder
import joblib

# Load the pre-trained Logistic Regression model
model_log = joblib.load('dementia_model.pkl')

# Define label encoders (fitted with training data categories)
label_encoders = {
    'Diabetic': LabelEncoder().fit([0, 1]),
    'Education_Level': LabelEncoder().fit([0, 1, 2, 3]),
    'Family_History': LabelEncoder().fit([0, 1]),
    'Smoking_Status': LabelEncoder().fit([0, 1, 2]),
    'APOE_ε4': LabelEncoder().fit([0, 1]),
    'Depression_Status': LabelEncoder().fit([0, 1]),
    'Physical_Activity': LabelEncoder().fit([0, 1, 2]),
    'Prescription': LabelEncoder().fit([0, 1, 2, 3, 4])
}

# Unique values for selectbox
education_levels = ['No School', 'Primary School', 'Secondary School', 'Diploma/Degree']
education_levels_mapping = {'No School': 0, 'Primary School': 1, 'Secondary School': 2, 'Diploma/Degree': 3}
family_history_options = ['No', 'Yes']
family_history_mapping = {'No': 0, 'Yes': 1}
smoking_status_options = ['Never Smoked', 'Former Smoker', 'Current Smoker']
smoking_status_mapping = {'Never Smoked': 0, 'Former Smoker': 1, 'Current Smoker': 2}
apoe_e4_options = ['Negative', 'Positive']
apoe_e4_mapping = {'Negative': 0, 'Positive': 1}
depression_status_options = ['No', 'Yes']
depression_status_mapping = {'No': 0, 'Yes': 1}
physical_activity_levels = ['Sedentary', 'Moderate Activity', 'Mild Activity']
physical_activity_mapping = {'Sedentary': 0, 'Moderate Activity': 1, 'Mild Activity': 2}
prescription_options = ['No prescription', 'Galantamine', 'Donepezil', 'Memantine', 'Rivastigmine']
prescription_mapping = {'No prescription': 0, 'Galantamine': 1, 'Donepezil': 2, 'Memantine': 3, 'Rivastigmine': 4}
diab_options = ['No', 'Yes']
diab_mapping = {'No': 0, 'Yes': 1}

def preprocess_input(data):
    # Create DataFrame from input data
    df = pd.DataFrame([data])

    # Encode categorical features
    for column in label_encoders:
        if column in df.columns:
            df[column] = label_encoders[column].transform(df[column])

    # Fill missing values if necessary (assuming 0 for simplicity)
    df.fillna(0, inplace=True)

    return df

def predict(user_input):
    # Preprocess the user input
    processed_input = preprocess_input(user_input)

    # Make prediction
    prediction = model_log.predict(processed_input)

    # Return the prediction
    return prediction[0]


