                "memory": "32G",
            },
        },
    },
}


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Plan and compile a bioinformatics workflow into WDL.",
    )

    source = parser.add_mutually_exclusive_group()
    source.add_argument(
        "--prompt",
        help="Natural-language workflow request. Uses a built-in RNA-seq demo prompt if no source is provided.",
    )
    source.add_argument(
        "--prompt-file",
        type=Path,
        help="Path to a UTF-8 text file containing a natural-language workflow request.",
    )
    source.add_argument(
        "-i",
        "--input",
        type=Path,
        help="Developer mode: path to a JSON/YAML Workflow IR or Recipe Tool Plan.",
    )

    parser.add_argument(
        "-o",
        "--output",
        type=Path,
        help="Path where the generated WDL should be written. Prints WDL when omitted.",
    )
    parser.add_argument(
        "--print-ir",
        action="store_true",
        help="Print the normalized Workflow IR after compilation.",
    )
    parser.add_argument(
        "--print-plan",
        action="store_true",
        help="Print the structured plan produced from natural language before compilation.",
    )
    parser.add_argument(
        "--save-plan",
        type=Path,
        help="Write the structured plan produced from natural language to JSON.",
    )
    parser.add_argument(
        "--save-planner-prompt",
        type=Path,
        help="Write the full natural-language planner prompt to a text file for debugging.",
    )
    parser.add_argument(
        "--no-check",
        action="store_true",
        help="Skip configured WDL syntax validation after rendering.",
    )
    parser.add_argument(
        "--planner-model",
        default=DEFAULT_PLANNER_MODEL,
        help=f"LLM model for natural-language planning. Default: {DEFAULT_PLANNER_MODEL}.",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="Write workflow progress logs to stderr.",
    )
    return parser.parse_args(argv)


def load_workflow_input(path: Path | None = None) -> dict[str, Any]:
    if path is None:
        return DEMO_INPUT

    raw_text = path.read_text(encoding="utf-8")
    if path.suffix.lower() in {".yaml", ".yml"}:
        data = yaml.safe_load(raw_text)
    else:
        data = json.loads(raw_text)

    if not isinstance(data, dict):
        raise ValueError(f"workflow input must be a JSON/YAML object: {path}")
    return data


def load_prompt(prompt: str | None = None, prompt_file: Path | None = None) -> str:
    if prompt_file is not None:
        return prompt_file.read_text(encoding="utf-8").strip()
    if prompt is not None:
        return prompt.strip()
    return DEMO_PROMPT


def write_wdl_output(path: Path, wdl_code: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(wdl_code, encoding="utf-8")


def write_json_output(path: Path, data: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def write_text_output(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    configure_logging(verbose=args.verbose)
    check = not args.no_check

    try:
        if args.input:
            parsed_json = load_workflow_input(args.input)
            planned_from_natural_language = False
            result = compile_structured_workflow(
                parsed_json,
                check=check,
            )
        else:
            prompt = load_prompt(args.prompt, args.prompt_file)
            if args.save_planner_prompt:
                write_text_output(args.save_planner_prompt, build_default_planner_prompt(prompt))
                print(f"Planner prompt written to {args.save_planner_prompt}", file=sys.stderr)

            result = plan_and_compile_workflow(
                prompt,
                model=args.planner_model,
                check=check,
            )
            parsed_json = result.plan or {}
            planned_from_natural_language = True

            if args.save_plan:
                write_json_output(args.save_plan, parsed_json)
                print(f"Planner plan written to {args.save_plan}", file=sys.stderr)

        final_state = result.state
    except NaturalLanguagePlanningError as exc:
        print(f"Natural language planning failed: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Compilation failed before workflow execution: {exc}", file=sys.stderr)
        return 1

    _print_report(final_state, check=check)

    if args.print_plan and planned_from_natural_language:
        print(json.dumps(parsed_json, indent=2, ensure_ascii=False))

    if args.print_ir and result.workflow_ir:
        print(json.dumps(result.workflow_ir, indent=2, ensure_ascii=False))

    if not result.succeeded:
        return 1

    if args.output:
        write_wdl_output(args.output, result.wdl)
        print(f"WDL written to {args.output}", file=sys.stderr)
    else:
        print(result.wdl)

    return 0


def configure_logging(verbose: bool = False) -> None:
    logging.basicConfig(
        level=logging.INFO if verbose else logging.WARNING,
        format="%(message)s",
        stream=sys.stderr,
        force=True,
    )


def _print_report(state: WorkflowState, check: bool) -> None:
    for action in state["repair_actions"]:
        print(f"repair: {action}", file=sys.stderr)

    for warning in state["analysis_warnings"]:
        print(f"warning: {warning}", file=sys.stderr)

    for error in state["analysis_errors"]:
        print(f"error: {error}", file=sys.stderr)

    if check and state["validation_message"]:
        print(state["validation_message"], file=sys.stderr)
    elif not check and state["validation_message"]:
        print(state["validation_message"], file=sys.stderr)


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""PostToolUse hook — track Skill tool invocations in session state.

Matcher: Skill

Records skill usage in skills-used-{session_id}.json so that
skill_guard.py can check sessionSkillUsed and allow edits.
"""

import json
import sys
from pathlib import Path

try:
    from _analytics import emit_event
except ImportError:

    def emit_event(*_a: object, **_k: object) -> None:
        pass


def record_skill_used(session_id: str, skill_name: str) -> None:
    """Record skill invocation in session state for skill_guard lookups."""
    hook_dir = Path(__file__).resolve().parent
    state_dir = hook_dir / "state"
    state_dir.mkdir(parents=True, exist_ok=True)
    state_path = state_dir / f"skills-used-{session_id}.json"

    state: dict[str, list[str]] = {"suggestedSkills": [], "usedSkills": []}
    if state_path.exists():
        try:
            with open(state_path) as f:
                state = json.load(f)
        except (json.JSONDecodeError, PermissionError):
            pass

    used = state.get("usedSkills", [])
    if skill_name not in used:
        used.append(skill_name)
    state["usedSkills"] = used

    with open(state_path, "w") as f:
        json.dump(state, f, indent=2)


def main() -> None:
    try:
        input_data = json.loads(sys.stdin.read())
    except (json.JSONDecodeError, EOFError):
        sys.exit(0)

    session_id = input_data.get("session_id", "unknown")
    tool_input = input_data.get("tool_input", {})
    skill_name = tool_input.get("name", "") or tool_input.get("skill", "")

    if not skill_name:
        sys.exit(0)

    record_skill_used(session_id, skill_name)

    emit_event(
        session_id,
        "hook.invoked",
        {
            "hook": "skill_tracker",
            "trigger": "PostToolUse",
            "outcome": "tracked",
            "skill": skill_name,
            "exit_code": 0,
        },
    )
    sys.exit(0)


if __name__ == "__main__":
    main()

"""
Complex Dynamic REST API Benchmark
Tests realistic API patterns: path params, query params, POST bodies, business logic
"""

from bustapi import BustAPI, jsonify, request

app = BustAPI()

# In-memory "database"
USERS = {
    1: {"id": 1, "name": "Alice", "email": "alice@example.com", "age": 28},
    2: {"id": 2, "name": "Bob", "email": "bob@example.com", "age": 34},
    3: {"id": 3, "name": "Charlie", "email": "charlie@example.com", "age": 22},
}

POSTS = {
    1: {
        "id": 1,
        "user_id": 1,
        "title": "Hello World",
        "body": "First post!",
        "likes": 42,
    },
    2: {
        "id": 2,
        "user_id": 1,
        "title": "BustAPI Rocks",
        "body": "So fast!",
        "likes": 128,
    },
    3: {
        "id": 3,
        "user_id": 2,
        "title": "Python Tips",
        "body": "Use type hints",
        "likes": 55,
    },
}

# ============== TURBO ROUTES (Zero Overhead) ==============
# Static responses, no params needed


@app.turbo_route("/api/health")
def health():
    return {"status": "healthy", "version": "1.0.0"}


@app.turbo_route("/api/stats")
def stats():
    return {
        "total_users": len(USERS),
        "total_posts": len(POSTS),
        "total_likes": sum(p["likes"] for p in POSTS.values()),
    }


# ============== REGULAR ROUTES (Full Features) ==============
# Dynamic responses with path/query params


@app.route("/api/users")
def list_users():
    return list(USERS.values())


@app.route("/api/users/<int:id>")
def get_user(id):
    user = USERS.get(id)
    if not user:
        return {"error": "User not found"}, 404
    return user


@app.route("/api/users/<int:id>/posts")
def get_user_posts(id):
    user_posts = [p for p in POSTS.values() if p["user_id"] == id]
    return user_posts


@app.route("/api/posts")
def list_posts():
    # Query param support: ?limit=X
    limit = request.args.get("limit", type=int, default=10)
    posts = list(POSTS.values())[:limit]
    return posts


@app.route("/api/posts/<int:id>")
def get_post(id):
    post = POSTS.get(id)
    if not post:
        return {"error": "Post not found"}, 404
    return post


@app.route("/api/posts/<int:id>/like", methods=["POST"])
def like_post(id):
    post = POSTS.get(id)
    if not post:
        return {"error": "Post not found"}, 404
    post["likes"] += 1
    return {"success": True, "new_likes": post["likes"]}


@app.route("/api/search")
def search():
    # Complex query: ?q=term&type=users|posts
    query = request.args.get("q", "")
    search_type = request.args.get("type", "all")

    results = {"users": [], "posts": []}

    if search_type in ("users", "all"):
        results["users"] = [
            u for u in USERS.values() if query.lower() in u["name"].lower()
        ]

    if search_type in ("posts", "all"):
        results["posts"] = [
            p for p in POSTS.values() if query.lower() in p["title"].lower()
        ]

    return results


@app.route("/api/users", methods=["POST"])
def create_user():
    data = request.get_json()
    new_id = max(USERS.keys()) + 1
    user = {
        "id": new_id,
        "name": data.get("name", "Anonymous"),
        "email": data.get("email", ""),
        "age": data.get("age", 0),
    }
    USERS[new_id] = user
    return user, 201


if __name__ == "__main__":
    print("Complex Dynamic REST API")
    print("=" * 40)
    print("Turbo routes: /api/health, /api/stats")
    print("Dynamic routes: /api/users, /api/posts, /api/search")
    print("=" * 40)
    app.run(host="127.0.0.1", port=5000, workers=8, debug=False)

"""Configuration management for the pipeline."""
import os
import yaml
from typing import Dict, Any
from pathlib import Path


class Config:
    """Pipeline configuration singleton."""

    _instance = None
    _config = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._load_config()
        return cls._instance

    @classmethod
    def _load_config(cls):
        """Load and validate configuration."""
        config_path = Path("/opt/airflow/config/pipeline_config.yaml")

        if not config_path.exists():
            raise FileNotFoundError(f"Config file not found: {config_path}")

        with open(config_path, 'r') as f:
            cls._config = yaml.safe_load(f)

        cls._config = cls._replace_env_vars(cls._config)

        # Validate required keys
        required_keys = [
            ('s3', 'endpoint'),
            ('s3', 'access_key'),
            ('s3', 'secret_key'),
            ('storage', 'bronze_bucket'),
            ('storage', 'silver_bucket'),
            ('storage', 'gold_bucket'),
        ]

        for keys in required_keys:
            if cls.get(*keys) is None:
                raise ValueError(f"Missing required config: {'.'.join(keys)}")

    @classmethod
    def _replace_env_vars(cls, config: Dict[str, Any]) -> Dict[str, Any]:
        """Recursively replace ${VAR} with environment variables."""
        if isinstance(config, dict):
            return {k: cls._replace_env_vars(v) for k, v in config.items()}
        elif isinstance(config, list):
            return [cls._replace_env_vars(item) for item in config]
        elif isinstance(config, str) and config.startswith("${") and config.endswith("}"):
            var_name = config[2:-1]
            return os.getenv(var_name, config)
        return config

    @classmethod
    def get(cls, *keys, default=None):
        """Get configuration value by nested keys."""
        value = cls._config
        for key in keys:
            if isinstance(value, dict):
                value = value.get(key)
            else:
                return default
            if value is None:
                return default
        return value


# Convenience function
def get_config(*keys, default=None):
    """Get configuration value."""
    return Config().get(*keys, default=default)

"""FastAPI composition root mounting the stateless Streamable HTTP MCP app."""

from __future__ import annotations

import hmac
from collections.abc import AsyncIterator, Awaitable, Callable
from contextlib import asynccontextmanager

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response
from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor
from prometheus_client import CONTENT_TYPE_LATEST, generate_latest

from recsys_feature_rag_mcp import __version__
from recsys_feature_rag_mcp.clients.online_features import OnlineFeatureClient
from recsys_feature_rag_mcp.clients.rag import RagClient
from recsys_feature_rag_mcp.server import create_mcp_server
from recsys_feature_rag_mcp.settings import McpSettings


def create_app(
    settings: McpSettings | None = None,
    feature_client: OnlineFeatureClient | None = None,
    rag_client: RagClient | None = None,
) -> FastAPI:
    """Compose FastAPI health endpoints with the authenticated MCP transport."""

    settings = settings or McpSettings.from_env()
    feature_client = feature_client or OnlineFeatureClient(
        base_url=settings.online_feature_api_url,
        timeout_seconds=settings.online_feature_timeout_seconds,
        max_connections=settings.downstream_max_connections,
        max_keepalive_connections=settings.downstream_max_keepalive_connections,
    )
    rag_client = rag_client or RagClient(
        base_url=settings.rag_api_url,
        timeout_seconds=settings.rag_timeout_seconds,
        max_connections=settings.downstream_max_connections,
        max_keepalive_connections=settings.downstream_max_keepalive_connections,
    )
    mcp = create_mcp_server(
        feature_client,
        rag_client,
        allowed_hosts=settings.allowed_hosts,
    )

    @asynccontextmanager
    async def lifespan(_: FastAPI) -> AsyncIterator[None]:
        """Start MCP sessions and close pooled downstream HTTP clients."""

        try:
            async with mcp.session_manager.run():
                yield
        finally:
            await feature_client.aclose()
            await rag_client.aclose()

    app = FastAPI(
        title="RecSys Feature and RAG MCP",
        version=__version__,
        lifespan=lifespan,
    )
    FastAPIInstrumentor.instrument_app(
        app,
        excluded_urls="healthz,ready,metrics",
    )

    @app.middleware("http")
    async def protect_mcp(
        request: Request,
        call_next: Callable[[Request], Awaitable[Response]],
    ) -> Response:
        """Require a bearer token and accepted browser origin on MCP routes."""

        if request.url.path.startswith("/mcp"):
            if not settings.auth_token:
                return JSONResponse({"detail": "MCP authentication unavailable"}, 503)
            supplied = request.headers.get("authorization", "")
            expected = f"Bearer {settings.auth_token}"
            if not hmac.compare_digest(supplied, expected):
                return JSONResponse({"detail": "unauthorized"}, 401)
            origin = request.headers.get("origin")
            if origin and origin not in settings.allowed_origins:
                return JSONResponse({"detail": "origin not allowed"}, 403)
        return await call_next(request)

    @app.get("/healthz")
    async def healthz() -> dict[str, str]:
        """Report process liveness without touching downstream services."""

        return {"status": "ok"}

    @app.get("/ready")
    async def ready() -> JSONResponse:
        """Report readiness only when MCP authentication is configured."""

        if not settings.auth_token:
            return JSONResponse({"status": "not_ready"}, status_code=503)
        return JSONResponse({"status": "ready"})

    @app.get("/version")
    async def version() -> dict[str, object]:
        """Expose immutable build and transport metadata."""

        return {
            "service": "recsys-feature-rag-mcp",
            "version": __version__,
            "image_reference": settings.image_reference,
            "transport": "streamable-http",
            "stateless": True,
        }

    @app.get("/metrics")
    async def metrics() -> Response:
        """Expose Prometheus metrics for tool and downstream operations."""

        return Response(generate_latest(), media_type=CONTENT_TYPE_LATEST)

    app.mount("/", mcp.streamable_http_app())
    return app


app = create_app()

import logging
import os
from importlib import import_module
from typing import Any

from django.apps import apps

Logger = logging.getLogger(__name__)

PLUGINS_APP = "plugins"
AUTH_PLUGIN_DIR = "authentication"
AUTH_MODULE_PREFIX = "scalekit"
AUTH_MODULE = "module"
AUTH_METADATA = "metadata"
METADATA_SERVICE_CLASS = "service_class"
METADATA_IS_ACTIVE = "is_active"


def _load_plugins() -> dict[str, dict[str, Any]]:
    """Iterate through authentication plugins and register their metadata."""
    auth_modules = {}
    try:
        auth_app = apps.get_app_config(PLUGINS_APP)
    except LookupError:
        Logger.info("No plugins app found. Running in OSS mode.")
        return auth_modules

    auth_package_path = auth_app.module.__package__
    auth_dir = os.path.join(auth_app.path, AUTH_PLUGIN_DIR)
    auth_package_path = f"{auth_package_path}.{AUTH_PLUGIN_DIR}"

    if not os.path.isdir(auth_dir):
        Logger.info("No authentication plugin directory found.")
        return auth_modules

    for item in os.listdir(auth_dir):
        if not item.startswith(AUTH_MODULE_PREFIX):
            continue
        if os.path.isdir(os.path.join(auth_dir, item)):
            auth_module_name = item
        elif item.endswith(".so"):
            auth_module_name = item.split(".")[0]
        else:
            continue
        try:
            full_module_path = f"{auth_package_path}.{auth_module_name}"
            module = import_module(full_module_path)
            metadata = getattr(module, AUTH_METADATA, {})
            if metadata.get(METADATA_IS_ACTIVE, False):
                auth_modules[auth_module_name] = {
                    AUTH_MODULE: module,
                    AUTH_METADATA: module.metadata,
                }
                Logger.info(
                    "Loaded auth plugin: %s, is_active: %s",
                    module.metadata["name"],
                    module.metadata["is_active"],
                )
        except ModuleNotFoundError as exception:
            Logger.error(
                "Error while importing authentication module: %s", exception
            )

    if len(auth_modules) > 1:
        raise ValueError(
            "Multiple authentication modules found. "
            "Only one authentication method is allowed."
        )
    elif len(auth_modules) == 0:
        Logger.info(
            "No authentication modules found. "
            "Application will start with default OSS authentication."
        )
    return auth_modules


class AuthenticationPluginRegistry:
    auth_modules: dict[str, dict[str, Any]] = _load_plugins()
    _service_instance: Any | None = None

    @classmethod
    def is_plugin_available(cls) -> bool:
        return len(cls.auth_modules) > 0

    @classmethod
    def get_plugin(cls) -> Any:
        if cls._service_instance is None:
            chosen_auth_module = next(iter(cls.auth_modules.values()))
            chosen_metadata = chosen_auth_module[AUTH_METADATA]
            service_class_name = chosen_metadata[METADATA_SERVICE_CLASS]
            cls._service_instance = service_class_name()
        return cls._service_instance

